// 未来天王 · 原生（2026-11-08 实测）
// 主域已从 .info 迁到 .cc：.info 只返回 301，客户端不跟随跨域跳转就会报"无法连接"
fn yxAbs(u) {
  let s = trim(str(u))
  if (s == '') { return '' }
  if (indexOf(s, 'http') == 0) { return s }
  if (indexOf(s, '//') == 0) { return 'http:' + s }
  return 'http://www.weilaitianwang.cc' + s
}
fn yxCover(h) {
  let m = match(str(h), '([0-9]+)_([0-9]+)', 2)
  if (m == null) { return '' }
  let id = str(m)
  return 'http://www.weilaitianwang.cc/files/article/image/' + str(floor(int(id, 0) / 1000)) + '/' + id + '/' + id + 's.jpg'
}
// 站点把换行存成字面量（反斜杠+n），用 split/join 全局还原
fn yxFixLines(t) {
  let bs = fromCharCode(92)
  let nl = fromCharCode(10)
  t = join(split(t, bs + 'r' + bs + 'n'), nl)
  t = join(split(t, bs + 'n'), nl)
  t = join(split(t, bs + 'r'), '')
  t = join(split(t, fromCharCode(13)), '')
  return t
}
// 简介：<br> 转换行 + 去标签
fn yxLines(h) {
  let s = str(h)
  let bs = fromCharCode(92)
  let nl = fromCharCode(10)
  s = replace(s, '<br' + bs + 's*/?>', nl, 'g')
  s = replace(s, '<[^>]*>', '', 'g')
  s = htmlDecode(s)
  s = yxFixLines(s)
  s = replace(s, nl + nl + nl, nl + nl, 'g')
  return trim(s)
}
// 正文：先切掉 center_tip，再去标签、清广告整行
fn yxBody(h) {
  let s = str(h)
  let a = indexOf(s, '<div id="center_tip">')
  if (a >= 0) { s = substring(s, 0, a) }
  let bs = fromCharCode(92)
  let nl = fromCharCode(10)
  s = replace(s, '<br' + bs + 's*/?>', nl, 'g')
  s = replace(s, '<' + bs + '/' + bs + 's*(p|div|dd|li|ul|ol|h[1-6]|tr|section)' + bs + 's*>', nl, 'g')
  s = replace(s, '<[^>]*>', '', 'g')
  s = htmlDecode(s)
  s = yxFixLines(s)
  s = replace(s, '[^' + nl + ']*https?://[^' + nl + ']*', '', 'g')
  s = replace(s, '[^' + nl + ']*天才一秒记住[^' + nl + ']*', '', 'g')
  s = replace(s, '[^' + nl + ']*最快更新[^' + nl + ']*', '', 'g')
  s = replace(s, '[^' + nl + ']*最新网址[^' + nl + ']*', '', 'g')
  s = replace(s, '[^' + nl + ']*请记住本站[^' + nl + ']*', '', 'g')
  s = replace(s, nl + nl + nl, nl + nl, 'g')
  s = replace(s, nl + nl + nl, nl + nl, 'g')
  s = replace(s, '[ \t]+\n', nl, 'g')
  return trim(s)
}

// 哔哩文库正文：保留插图 <img> 和它的懒加载属性，只清掉多余标签
// 站点两类图：前 2 张 eager 用 src，其余 lazy 用 data-src（配 lazysizes），都要认
fn blUrl(tag) {
  let t = str(tag)
  let u = match(t, 'data-src="([^"]+)"', 1)            // 懒加载图优先
  if (str(u) == '') {
    u = match(t, 'src="([^"]+)"', 1)
  }
  if (str(u) == '') { return '' }
  return str(u)
}

// 保留原站的 loading 属性：eager 的立刻加载，lazy 的滚到才加载。
// 丢掉它会让阅读器一进章节就抓全部插图（实测一章 15~20 张、单张 235~431KB）。
fn blImg(tag) {
  let t = str(tag)
  let u = blUrl(t)
  if (u == '') { return '' }
  let ld = match(t, 'loading="([^"]+)"', 1)
  if (str(ld) == '') { return '<img src="' + u + '">' }
  return '<img src="' + str(u) + '" loading="' + str(ld) + '">'
}

fn blBody(h) {
  let s = str(h)
  // 图片框自带的兜底文案，先整块删掉
  s = replace(s, '<span[^>]*image-error[^>]*>[^<]*</span>', '', 'g')
  s = replace(s, '<br[^>]*>', fromCharCode(10), 'gi')
  s = replace(s, '</p>', fromCharCode(10), 'gi')
  // 去掉除 <img> 以外的所有标签
  s = replace(s, '<\/?(?!img\b)[a-zA-Z][^>]*>', '', 'g')
  // 图片统一成 <img src="..." loading="...">，供阅读器当插图渲染
  s = replace(s, '<img[^>]*>', m => blImg(m[0]), 'gi')
  s = htmlDecode(s)
  let out = []
  for line in split(s, fromCharCode(10)) {
    let x = trim(str(line))
    if (x != '') { push(out, x) }
  }
  return join(out, fromCharCode(10))
}

