function qdToc(ctx) {
  var bid = native.match(ctx.book.bookUrl, 'book/(\\d+)', 1);
  if (!bid) throw new Error('无法从书籍地址取得书号：' + ctx.book.bookUrl);
  var url = 'https://wxapp.qidian.com/api/book/categoryV2?bookId=' + bid;
  var res = http.get(url);
  if (!res.ok) throw new Error('目录接口请求失败：HTTP ' + res.status);
  var payload = res.json();
  if (!payload || payload.code !== 0 || !payload.data || !payload.data.vs) throw new Error('目录接口返回异常');
  var chapters = [];
  payload.data.vs.forEach(function (volume) {
    if (volume.vN) chapters.push({ title: volume.vN, isVolume: true });
    (volume.cs || []).forEach(function (item) {
      chapters.push({
        title: item.cN,
        url: 'https://m.qidian.com/chapter/' + bid + '/' + item.id + '/',
        isVip: item.sS === 0,
        tag: (item.uT || '') + (item.cnt ? ' · ' + item.cnt + '字' : '')
      });
    });
  });
  if (!chapters.length) throw new Error('目录为空，站点可能调整了目录接口');
  return chapters;
}

function catUrl(c, st, so, wd, up, pg) {
  var u = '/book/bookclass.html?c=' + c + '&page=' + pg;
  if (st === '连载') u += '&bookStatus=0';
  else if (st === '完结') u += '&bookStatus=1';
  if (wd === '30万以下') u += '&wordCountMax=300000';
  else if (wd === '30-50万') u += '&wordCountMin=300000&wordCountMax=500000';
  else if (wd === '50-100万') u += '&wordCountMin=500000&wordCountMax=1000000';
  else if (wd === '100万以上') u += '&wordCountMin=1000000&wordCountMax=999999999';
  if (up === '三日内') u += '&updatePeriod=3';
  else if (up === '七日内') u += '&updatePeriod=7';
  else if (up === '半月内') u += '&updatePeriod=15';
  else if (up === '一月内') u += '&updatePeriod=30';
  if (so === '人气') u += '&sort=visit_count';
  else if (so === '字数') u += '&sort=word_count';
  else if (so === '更新') u += '&sort=last_index_update_time';
  return 'https://book.washai.net' + u;
}

// ===== 过期杂志（我爱过期杂志网）· 原生书源 · 实时取数 =====
var MG_BASE = 'https://www.52dzxy.com';
var MG_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0.0.0 Safari/537.36';

function mgRealtime(ctx) {
  return String((ctx && ctx.vars && ctx.vars.realtime) || '开') !== '关';
}
function mgHeaders() {
  return { 'User-Agent': MG_UA, 'Referer': MG_BASE + '/', 'Accept-Language': 'zh-CN,zh;q=0.9' };
}
// 站点挂在 Cloudflare 后，max-age=14400 且缓存里混有旧版页面。
// 每次请求附加唯一参数使 cf-cache-status 变为 MISS，回源取最新版本。
function mgFresh(url) {
  // 按 4 小时一档取整：与站点 Cloudflare 的 cache-control max-age=14400 完全对齐。
  // 同一档内所有请求共享 CF 缓存（秒开）；换档后自动回源，新刊最多 4 小时可见。
  // 想立刻取最新，用书源设置里的「刷新最新内容」。
  var slot = Math.floor(Date.now() / 14400000);
  var bump = 0;
  try { bump = Number(cache.get('mgbump') || 0) || 0; } catch (e) { bump = 0; }
  var sep = url.indexOf('?') >= 0 ? '&' : '?';
  return url + sep + '_t=' + slot + (bump ? '-' + bump : '');
}
// fresh 只给列表页（首页 / 分类页）用：它们才需要考虑「有没有新期刊」。
// 期刊页、正文页内容静态，走 CDN 缓存并用 ttl 短缓存，避免每章都回源。
function mgGen() { try { return String(cache.get('mggen') || '1'); } catch (e) { return '1'; } }
function mgGet(ctx, url, fresh, ttl) {
  var ck = ttl ? 'mgp:' + mgGen() + ':' + url : '';
  if (ck) { try { var hit = cache.get(ck); if (hit) return { body: hit, base: url }; } catch (e) {} }
  var u = fresh ? mgFresh(url) : url;
  var r = http.get(u, { headers: mgHeaders(), timeout: 20000 });
  if (!r.ok) throw new Error('HTTP ' + r.status + ' ' + (r.error || ''));
  var body = r.body || '';
  if (!body) throw new Error('空响应');
  if (ck) { try { cache.put(ck, body, ttl); } catch (e) {} }
  return { body: body, base: url };
}
// 相对地址补全（base 用不带 _t 的干净地址）
function mgAbs(base, href) {
  href = String(href || '').split('#')[0].split('?')[0];
  if (!href) return '';
  if (/^https?:\/\//i.test(href)) return href;
  if (href.charAt(0) === '/') return MG_BASE + href;
  var parts = String(base).split('?')[0].split('/');
  parts.pop();
  var seg = href.split('/');
  for (var i = 0; i < seg.length; i++) {
    var s = seg[i];
    if (!s || s === '.') continue;
    if (s === '..') parts.pop();
    else parts.push(s);
  }
  return parts.join('/');
}
// 封面必须用站点原生 URL：期刊页 <img src="期号.jpg"> 就是它，CDN 缓存早已预热（HIT，约 0.7s）。
// 曾试过加 ?v=2 固定参数绕开宿主失败缓存，但新参数会成为独立 CDN 缓存键，
// 每张封面首次访问都要回源（实测 1.8~3.0s），得不偿失。URL 从「带参」变回「原生」
// 本身也足以让宿主的封面缓存重新下载一次。
function mgPic(u) { return u || ''; }
// 封面全部零请求推导：新版 /2026/bkzs/202614/index.html -> 202614.jpg
// 旧版 /2023/jrwz/index_24.html -> jrwz202324.jpg
//      /2024/gyxyb/index_gyxyb20248.html -> gyxyb20248.jpg
function mgCover(issueUrl) {
  var u = String(issueUrl || '').split('?')[0];
  var m = u.match(/\/(\d{4,7})\/index\.html$/);
  if (m) return mgPic(u.replace(/index\.html$/, m[1] + '.jpg'));
  var m2 = u.match(/^(.*\/)(\d{4})\/([a-z0-9]+)\/(index_[^/]+)\.html$/);
  if (m2) {
    var dir = m2[1] + m2[2] + '/' + m2[3] + '/';
    var tail = m2[4].slice(6);
    if (/^\d+$/.test(tail)) return mgPic(dir + m2[3] + m2[2] + tail + '.jpg');
    var num = tail.replace(/^[a-z0-9]+?(\d{4,7})$/, '$1');
    if (num) return mgPic(dir + m2[3] + num + '.jpg');
  }
  return '';
}
function mgNow() {
  var d = new Date();
  function p(n) { return n < 10 ? '0' + n : String(n); }
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
}
// 旧格式期刊（index_N.html）无规律封面，并发取期刊页里的 .jpg 图补齐
function mgFillCovers(ctx, items, cap) {
  cap = cap || 12;
  var miss = [];
  for (var i = 0; i < items.length && miss.length < cap; i++) if (!items[i].coverUrl) miss.push(i);
  if (!miss.length) return items;
  var reqs = [];
  for (var j = 0; j < miss.length; j++) {
    // 补封面取的是静态期刊页，走 CDN 缓存即可，无需回源
    reqs.push({ url: items[miss[j]].bookUrl.split('?')[0], headers: mgHeaders(), timeout: 12000 });
  }
  var rs;
  try { rs = http.all(reqs, { concurrency: 8, timeout: 12000 }); } catch (e) { return items; }
  for (var k = 0; k < miss.length; k++) {
    var r = rs && rs[k];
    if (!r || !r.ok || !r.body) continue;
    var im = r.body.match(/<img[^>]*class="magazine-cover"[^>]*src="([^"]+)"/) ||
             r.body.match(/<img[^>]*src="([^"]+\.jpg)"/);
    if (im && im[1] !== '.jpg' && !/template|logo/i.test(im[1])) {
      items[miss[k]].coverUrl = mgPic(mgAbs(items[miss[k]].bookUrl, im[1]));
    }
  }
  return items;
}
// 首页列表 30 秒短缓存：站点按天更新，30 秒不影响实时性，但能省掉发现页/搜索的重复请求
function mgHome(ctx) {
  var ck = 'mghome';
  var hit = cache.get(ck);
  if (hit) return hit;
  var body = mgGet(ctx, MG_BASE + '/index.html', mgRealtime(ctx)).body;
  try { cache.put(ck, body, 30); } catch (e) {}
  return body;
}

// ===== 杂志分类：从首页实时提取（站点新增杂志会自动出现）=====
function mgCats(ctx) {
  var h = mgHome(ctx);
  var out = [];
  var re = /<h2 class="magazine-title">([^<]+)<\/h2>[\s\S]*?href="([a-z0-9]+)\/all\.html"/g;
  var m;
  while ((m = re.exec(h)) !== null) out.push({ name: m[1].trim(), slug: m[2] });
  if (!out.length) {
    out = [
      { name: '读者', slug: 'duzhe' }, { name: '百科知识', slug: 'bkzs' }, { name: '父母必读', slug: 'fmbd' },
      { name: '新民周刊', slug: 'xmzk' }, { name: '第一财经', slug: 'dycj' }, { name: '南风窗', slug: 'nfc' },
      { name: '环球人物', slug: 'hqrw' }, { name: '轻兵器', slug: 'qbq' }, { name: '知识就是力量', slug: 'zsjsll' },
      { name: '中小学心理健康教育', slug: 'zxxxljkjy' }, { name: '中国经济周刊', slug: 'zgjjzk' },
      { name: '证券市场周刊', slug: 'zqsczk' }, { name: '股市状态分析', slug: 'gsdtfx' }, { name: '财经', slug: 'caijing' },
      { name: '婚姻与家庭·性情读本', slug: 'hyyjtxqdb' }, { name: '南方人物周刊', slug: 'nfrwzk' },
      { name: '中国新闻周刊', slug: 'zgxwzk' }, { name: '看世界', slug: 'ksj' }, { name: '阅读时代', slug: 'ydsd' },
      { name: '格言·校园版', slug: 'gyxyb' }, { name: '海外文摘', slug: 'hwwz' },
      { name: '思维与智慧·上半月', slug: 'swyzhsby' }, { name: '青年文摘', slug: 'qnwz' }, { name: '今日文摘', slug: 'jrwz' }
    ];
  }
  return out;
}

function mgBook(x) {
  return {
    name: x.name,
    author: x.magazine || '过期杂志',
    kind: x.kind || ((x.year ? x.year + ' · ' : '') + (x.issue || '')),
    intro: x.intro || '',
    coverUrl: mgCover(x.url),
    lastChapter: '',
    wordCount: '',
    bookUrl: x.url,
    tocUrl: x.url,
    type: 'text'
  };
}

// ===== 全站最新一期：首页每本杂志的第一期 =====
function mgLatest(ctx) {
  var h = mgHome(ctx);
  var parts = h.split(/<h2 class="magazine-title">/);
  var out = [];
  for (var i = 1; i < parts.length; i++) {
    var seg = parts[i];
    var nm = seg.match(/^([^<]+)<\/h2>/);
    if (!nm) continue;
    var name = nm[1].trim();
    var aRe = /<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g, a;
    while ((a = aRe.exec(seg)) !== null) {
      if (/all\.html/.test(a[1]) || /更多/.test(a[2])) continue;
      var issue = a[2].trim();
      out.push({ name: name + ' · ' + issue, magazine: name, issue: issue, year: '',
        intro: '本站最新一期',
        url: mgAbs(MG_BASE + '/index.html', a[1]) });
      break;
    }
  }
  return out;
}

// ===== 单个杂志的全部期刊：{slug}/all.html =====
function mgIssues(ctx, slug) {
  var u = MG_BASE + '/' + slug + '/all.html';
  var h = mgGet(ctx, u, mgRealtime(ctx)).body;
  var tm = h.match(/<title>([^<]*)<\/title>/);
  var magazine = tm ? String(tm[1]).replace(/\s*-\s*全部期刊.*$/, '').trim() : slug;
  var out = [];
  var ys = h.split(/<h2 class="year-title">/);
  for (var k = 1; k < ys.length; k++) {
    var ym = ys[k].match(/^([^<]+)<\/h2>/);
    var year = ym ? ym[1].trim() : '';
    var aRe = /<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g, a;
    while ((a = aRe.exec(ys[k])) !== null) {
      if (!/index[^/]*\.html$/i.test(a[1])) continue;
      if (!/\d{4}\//.test(a[1])) continue;
      if (/更多/.test(a[2])) continue;
      var issue = a[2].trim();
      out.push({ name: magazine + ' · ' + issue, magazine: magazine, issue: issue, year: year, url: mgAbs(u, a[1]) });
    }
  }
  if (!out.length) {
    var re2 = /<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g, b;
    while ((b = re2.exec(h)) !== null) {
      if (!/index[^/]*\.html$/i.test(b[1]) || !/\d{4}\//.test(b[1])) continue;
      out.push({ name: magazine + ' · ' + b[2].trim(), magazine: magazine, issue: b[2].trim(), year: '', url: mgAbs(u, b[1]) });
    }
  }
  return out;
}

// ===== 目录：兼容新版 catalog-section 与旧版 maglistbox =====
function mgTocRaw(h, base) {
  var out = [];
  var secRe = /<section class="catalog-section">([\s\S]*?)<\/section>/g, s;
  while ((s = secRe.exec(h)) !== null) {
    var vm = s[1].match(/<h2 class="catalog-section-title">([^<]+)<\/h2>/);
    var vol = vm ? vm[1].trim() : '';
    var first = '';
    var arts = [];
    var aRe = /<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g, a;
    while ((a = aRe.exec(s[1])) !== null) {
      var u = mgAbs(base, a[1]);
      if (!first) first = u;
      arts.push({ title: a[2].trim(), url: u, tag: vol, isVolume: false });
    }
    for (var i = 0; i < arts.length; i++) out.push(arts[i]);
  }
  if (out.length) return out;
  var dlRe = /<dl>([\s\S]*?)<\/dl>/g, d;
  while ((d = dlRe.exec(h)) !== null) {
    var vm2 = d[1].match(/<dt><span>([^<]+)<\/span>/);
    var vol2 = vm2 ? vm2[1].trim() : '';
    var first2 = '';
    var arts2 = [];
    var aRe2 = /<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g, a2;
    while ((a2 = aRe2.exec(d[1])) !== null) {
      var u2 = mgAbs(base, a2[1]);
      if (!first2) first2 = u2;
      arts2.push({ title: a2[2].trim(), url: u2, tag: vol2, isVolume: false });
    }
    for (var j = 0; j < arts2.length; j++) out.push(arts2[j]);
  }
  return out;
}

// ===== 搜索：首页内匹配杂志名 / 期号（站点无服务端搜索）=====
function searchBooks(ctx) {
  var key = String(ctx.key || '').trim();
  var h = mgHome(ctx);
  var parts = h.split(/<h2 class="magazine-title">/);
  var out = [];
  var seen = {};
  var hitSlugs = [];
  for (var i = 1; i < parts.length; i++) {
    var nm = parts[i].match(/^([^<]+)<\/h2>/);
    if (!nm) continue;
    var name = nm[1].trim();
    var allM = parts[i].match(/href="([a-z0-9]+)\/all\.html"/);
    var aRe = /<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g, a;
    while ((a = aRe.exec(parts[i])) !== null) {
      if (/all\.html/.test(a[1]) || /更多/.test(a[2])) continue;
      var issue = a[2].trim();
      if (key && (name + issue).indexOf(key) < 0) continue;
      var u = mgAbs(MG_BASE + '/index.html', a[1]);
      if (seen[u]) continue;
      seen[u] = 1;
      out.push(mgBook({ name: name + ' · ' + issue, magazine: name, issue: issue, url: u }));
    }
    // 杂志名本身命中时，展开该杂志全部年份期刊
    if (allM && key && name.indexOf(key) >= 0) hitSlugs.push(allM[1]);
    if (out.length >= 30) return out;
  }
  // 关键词是年份/期号等，首页不够时再按杂志名匹配补全
  if (out.length < 30 && key && !hitSlugs.length) {
    for (var k = 1; k < parts.length && out.length < 30; k++) {
      var nm2 = parts[k].match(/^([^<]+)<\/h2>/);
      if (!nm2) continue;
      var allM2 = parts[k].match(/href="([a-z0-9]+)\/all\.html"/);
