fn clean(html) {
  let t = stripHtml(html)
  let out = []
  for line in split(t, '\n') {
    let s = trim(line)
    if (s != '') { push(out, s) }
  }
  return join(out, '\n')
}

fn body(html) {
  let h = replace(html, '<center[^>]*chapterPages.*?</center>', '', 's')
  h = replace(h, '<font[^>]*>[^<]*本章未完[^<]*</font>', '')
  h = replace(h, '<font[^>]*>[^<]*数字分页[^<]*</font>', '')
  let t = stripHtml(h)
  let out = []
  for line in split(t, '\n') {
    let s = trim(line)
    if (s != '' && !startsWith(s, '标签：') && !contains(s, '本章完') && !contains(s, '本章未完') && !contains(s, '数字分页') && !contains(s, '最新章节请访问')) {
      push(out, s)
    }
  }
  return join(out, '\n')
}

// base64 + XOR(i%127+1) 解站点混淆文本
fn blDec(s) {
  let b = base64Bytes(str(s))
  let out = []
  let i = 0
  while (i < len(b)) {
    push(out, b[i] ^ ((i % 127) + 1))
    i = i + 1
  }
  return fromBytes(out)
}
// 正文分页：锚文本「下一页」的链接
fn blNext(h) {
  return str(match(str(h), 'href="([^"]+)"[^>]*>[ ]*下一页', 1))
}
// 详情：分类 · 状态
fn blMeta(h) {
  let c = str(match(str(h), "<dt>分类：</dt>\s*<dd><a[^>]*>([^<]+)</a>", 1))
  let s = str(match(str(h), "<dt>状态：</dt>\s*<dd>([^<]+)</dd>", 1))
  if (len(s) == 0) { return c }
  if (len(c) == 0) { return s }
  return c + " · " + s
}
// 正文：把 .content 下所有 data-obf 取出并逐段解码
fn blBody(h) {
  let all = matchAll(str(h), 'data-obf="([^"]+)"', 1)
  let out = []
  let i = 0
  while (i < len(all)) {
    push(out, blDec(str(all[i])))
    i = i + 1
  }
  return join(out, fromCharCode(10))
}
// 简介：标签 + 解码后的正文
fn blIntro(h) {
  let tags = matchAll(str(h), 'tag-label[^>]*>([^<]+)<', 1)
  let t = join(tags, "、")
  if (len(t) == 0) { t = "无" }
  let obf = str(match(str(h), 'obf-html"[^>]*data-obf-html="([^"]+)"', 1))
  let txt = ""
  if (len(obf) > 0) { txt = blDec(obf) }
  return "🏷 标签：" + t + fromCharCode(10) + fromCharCode(10) + txt
}
// 目录分页：只给下一页（串行），避免每页都全量生成造成重复章节
fn blNextPage(bu, h) {
  let id = str(match(str(bu), "/book/([0-9]+)\\.html", 1))
  if (len(id) == 0) { return "" }
  let cur = int(default(match(str(bu), "cp=([0-9]+)", 1), "1"), 1)
  let all = matchAll(str(h), "cp=([0-9]+)", 1)
  let mx = 0
  let i = 0
  while (i < len(all)) {
    let v = int(str(all[i]), 0)
    if (v > mx) { mx = v }
    i = i + 1
  }
  let nx = cur + 1
  if (nx > mx) { return "" }
  return "https://www.boluomao1.com/book/" + id + ".html?cp=" + str(nx) + "#chapters"
}
// 简介：obf 密文 > .des 正文 > meta description；最后统一去标签
fn blDesc(h) {
  let s = str(h)
  let t = ""
  let o = str(match(s, 'class="obf-html[^>]*data-obf-html="([^"]+)"', 1))
  if (len(o) > 0) {
    t = blDec(o)
  } else {
    let p = str(match(s, 'class="des"[^>]*>[\\s\\S]{0,80}?<p>([^<]{1,2000})', 1))
    if (len(p) > 0) {
      t = p
    } else {
      t = str(match(s, 'name="description"[^>]*content="([^"]{1,800})', 1))
      let k = indexOf(t, "简介：")
      if (k >= 0) {
        t = substring(t, k + 3, len(t))
      }
    }
  }
  t = replace(t, "<br[ ]*[/]?>", fromCharCode(10))
  t = replace(t, "[<][^>]*[>]", "")
  t = replace(t, fromCharCode(13), "")
  return trim(t)
}

