// 搜索：主通道 rrssk.com（第三方，带当日签名）；失败则走本站作者页兜底
function b64d(s) {
  var T = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  var o = "", i, a, b2, c, d2;
  s = String(s || "").replace(/[^A-Za-z0-9+/=]/g, "");
  for (i = 0; i < s.length; i += 4) {
    a = T.indexOf(s.charAt(i)); b2 = T.indexOf(s.charAt(i + 1));
    c = T.indexOf(s.charAt(i + 2)); d2 = T.indexOf(s.charAt(i + 3));
    if (a < 0 || b2 < 0) { break; }
    o += String.fromCharCode((a << 2) | (b2 >> 4));
    if (c >= 0) { o += String.fromCharCode(((b2 & 15) << 4) | (c >> 2)); }
    if (d2 >= 0) { o += String.fromCharCode(((c & 3) << 6) | d2); }
  }
  return o;
}
// 解析本站列表卡片（列表页 / 作者页同构）
function parseCards(h) {
  var out = [], segs = String(h || "").split("<li>"), i;
  for (i = 1; i < segs.length; i++) {
    var s = segs[i];
    var hm = s.match(/href="[^"]*?([0-9]+)[.]html"/);
    var nm = s.match(/<div class="name[^"]*">[^<]*<a[^>]*>([^<]+)</);
    if (!hm || !nm) { continue; }
    var cv = s.match(/<img[^>]*src="([^"]+)"/);
    var au = s.match(/[<][/]svg[>]([^<]*)</);
    var kd = s.match(/class="label">([^<]*)</);
    var stm = s.match(/class="tip[^"]*">([^<]*)</);
    out.push({
      name: nm[1].trim(),
      author: au ? au[1].trim() : "",
      kind: kd ? kd[1].trim() : "",
      status: stm ? stm[1].trim() : "",
      coverUrl: cv ? cv[1] : "",
      bookUrl: "https://www.boluomao1.com/book/" + hm[1] + ".html"
    });
  }
  return out;
}
function blSearch(ctx) {
  var SA = "https://www.boluomao1.com";
  var B = "https://www.rrssk.com";
  var key = String((ctx && ctx.key) || "").trim();
  if (key.length < 1) { return []; }
  var kw = key.length < 2 ? key + "的" : key;
  var rrErr = "";
  try {
    var st = Date.now();
    var page = null;
    for (var pa = 0; pa < 2 && !page; pa++) {
      try { page = http.get(B + "/boluomao.html?_=" + st, { timeout: 4000 }); } catch (e1) { page = null; }
      if (page && !page.ok) { page = null; }
    }
    if (!page) { throw new Error("入口无响应"); }
    var html = String(page.body || "");
    var tk = (html.match(/name="_t"[^>]*?value="([^"]+)"/) || [])[1];
    var vv = (html.match(/signJs&v=([^"&]+)/) || [])[1];
    if (!tk || !vv) { throw new Error("搜索页结构变化"); }
    var jr = null;
    var ck = "blmSign:" + vv;
    try { var hit = cache.get(ck); if (hit) { jr = { ok: true, body: hit }; } } catch (e2) {}
    if (!jr) {
      try { jr = http.get(B + "/?action=signJs&v=" + vv + "&_=" + st, { timeout: 6000 }); } catch (e3) { jr = null; }
      if (jr && jr.ok && jr.body) { try { cache.put(ck, String(jr.body), 21600); } catch (e4) {} }
    }
    var jsrc = String((jr && jr.body) || "");
    var gm = jsrc.match(/typeof[ ]+(_[0-9a-zA-Z]+)[ ]*!==[ ]*["][n][u][m][b][e][r]["][ ]*[|][|][ ]*(_[0-9a-zA-Z]+)[ ]*!==[ ]*([0-9]+)/);
    var fh = jsrc.match(/function[ ]+(_[0-9a-zA-Z]+)[ ]*[(][ ]*s[ ]*,[ ]*t[ ]*,[ ]*ts[ ]*[)][ ]*[{]/);
    if (!gm || !fh) { throw new Error("签名脚本结构变化"); }
    var dep = 0, ge = -1;
    for (var i = fh.index; i < jsrc.length; i++) {
      var ch = jsrc.charAt(i);
      if (ch === "{") { dep++; } else if (ch === "}") { dep--; if (dep === 0) { ge = i; break; } }
    }
    if (ge < 0) { throw new Error("签名函数体配对失败"); }
    var SF = eval("var " + gm[1] + "=" + gm[3] + ";" + jsrc.substring(fh.index, ge + 1) + ";" + fh[1]);
    if (typeof SF !== "function") { throw new Error("签名器构造失败"); }
    var enc = encodeURIComponent(kw).replace(/[!][(][)][*]/g, function (c0) {
      return "%" + c0.charCodeAt(0).toString(16).toUpperCase();
    });
    var ts = Math.floor(Date.now() / 1000);
    var sg = SF(enc, tk, ts);
    var res = http.post(B + "/?action=search", "keyword=" + enc + "&_t=" + tk + "&_ts=" + ts + "&_s=" + sg, {
      timeout: 8000,
      headers: { "Origin": B, "Referer": B + "/boluomao.html", "Content-Type": "application/x-www-form-urlencoded" }
    });
    if (!res || !res.ok) { throw new Error("搜索接口 HTTP " + (res ? res.status : "超时")); }
    var out = String(res.body || "");
    var books = [];
    var segs2 = out.split('<div class="book-card"');
    for (var k = 1; k < segs2.length; k++) {
      var blk = segs2[k];
      var nmM = blk.match(/_title[^>]*>([^<]+)</);
      var ocM = blk.match(/onclick="([^"]+)"/);
      if (!nmM || !ocM) { continue; }
      var tM = ocM[1].match(/t=([^&]+)/);
      if (!tM) { continue; }
      var url = b64d(decodeURIComponent(tM[1])).replace("www.boluomao.com", "www.boluomao1.com");
      if (url.indexOf("http") !== 0) { continue; }
      var auM = blk.match(/作者：[<][/]span[>]([^<]*)</);
      var kdM = blk.match(/分类：[<][/]span[>]([^<]*)</);
      var cvM = blk.match(/_cover[^<]*<img[^>]*src="([^"]+)"/);
      var inM = blk.match(/_desc[^>]*>([^<]*)</);
      var stM = blk.match(/book-tag--status[^>]*>([^<]*)</);
      books.push({
        name: nmM[1].trim(),
        author: auM ? auM[1].trim() : "",
        kind: kdM ? kdM[1].trim() : "",
        status: stM ? stM[1].trim() : "",
        intro: inM ? inM[1].replace(/^[ ]+/, "").trim() : "",
        coverUrl: cvM ? cvM[1] : "",
        bookUrl: url
      });
    }
    if (books.length > 0) { return books; }
  } catch (e5) { rrErr = String((e5 && e5.message) || e5); }
  // 兜底：本站作者页（rrssk 挂了也能按作者名搜到书）
  var au2 = null;
  try { au2 = http.get(SA + "/author/" + encodeURIComponent(key) + "/", { timeout: 8000 }); } catch (e6) { au2 = null; }
  if (au2 && au2.ok && au2.body) {
    var list = parseCards(String(au2.body));
    if (list.length > 0) { return list; }
  }
  if (rrErr) { throw new Error("搜索服务不可用（" + rrErr + "），本站也没有同名作者"); }
  return [];
}

function qbgToc(ctx) {
  var r = http.get(ctx.book.tocUrl);
  if (!r.ok) throw new Error('目录请求失败：' + (r.error || r.status));
  var h = r.body;
  var ts = native.selAll('@css:#list dd a@text', h);
  var hs = native.selAll('@css:#list dd a@href', h);
  var last = {}, map = {};
  for (var i = 0; i < hs.length; i++) {
    var u = hs[i];
    if (!u) continue;
    last[u] = i;
    map[u] = { title: ts[i] || ('第' + (i + 1) + '章'), url: (u.indexOf('http') === 0 ? u : ('https://www.qibuge.com' + u)) };
  }
  var keys = Object.keys(last);
  if (!keys.length) throw new Error('没有解析到目录');
  keys.sort(function (a, b) { return last[a] - last[b]; });
  var out = [];
  for (var j = 0; j < keys.length; j++) out.push(map[keys[j]]);
  return out;
}

