// ── 天域小说网：只有移动站 m.zmccx.com 可访问（www.zmccx.com 已不通）
fn sdRoot(u) {
  let m = match(str(u), '^(https?://[^/]+)', 1)
  if (str(m) == '') { return 'http://wap.tycqzw.info' }
  return str(m)
}

fn sdAbs(u, base) {
  let s = trim(str(u))
  if (s == '') { return '' }
  if (test(s, '^https?://')) { return s }
  if (!startsWith(s, '/')) { s = '/' + s }
  return sdRoot(base) + s
}

// 书目录形如 /190_190931/，取「190_190931」
fn sdBid(u) {
  let m = match(str(u), '/([0-9]+_[0-9]+)/', 1)
  return str(m)
}

// 封面：/files/article/image/{floor(书码/1000)}/{书码}/{书码}s.jpg
fn sdCover(u, base) {
  let id = sdBid(u)
  if (id == '') { return '' }
  // 站点封面路径把 23_23808 拆成 23/23808/23808s.jpg（下划线变目录层级，文件名只取后段）
  let parts = split(id, '_')
  if (len(parts) < 2) { return '' }
  let a = str(parts[0])
  let b = str(parts[1])
  return sdRoot(base) + '/files/article/image/' + a + '/' + b + '/' + b + 's.jpg'
}

// ── 目录：all.html 一页铺完整本
// 页内混着「↓直达页面底部」(href=#bottom) 和页脚链接，它们也能被 href 正则命中，
// 所以必须同时要求【地址含本书目录段】且【以数字.html 结尾】。
// ⚠ match 未命中返回空串而不是 null，判断一律用 str(x) == ''。
fn sdToc(html, bookUrl) {
  let h = str(html)
  let b = sdBid(bookUrl)
  if (b == '') { return [] }
  let base = sdRoot(bookUrl)
  let prefix = '/' + b + '/'
  let q = fromCharCode(39)
  let res = []
  let parts = split(h, '<a ')
  let i = 1
  let k = 0
  while (i < len(parts)) {
    let seg = str(parts[i])
    i = i + 1
    let href = str(match(seg, 'href=[' + q + '"]' + '([^' + q + '"]+)[' + q + '"]', 1))
    let no = match(href, '([0-9]+)\\.html$', 1)
    if (str(no) != '' && indexOf(href, prefix) >= 0) {
      let title = trim(str(match(seg, '^[^>]*>([^<]*)</a>', 1)))
      if (title != '') {
        let u = href
        if (!test(u, '^https?://')) {
          if (!startsWith(u, '/')) { u = '/' + u }
          u = base + u
        }
        res[k] = { title: title, url: u }
        k = k + 1
      }
    }
  }
  return res
}

// ── 章节内分页：页内带「第(1/3)页」
// 最后一页的「下一章」指向目录页（/190_190931/），不能跟随，
// 分页地址一律按 base + _N.html 自己拼。
fn sdPageBase(u) {
  let s = str(u)
  let m = match(s, '^(.*?)_[0-9]+\\.html$', 1)
  if (str(m) != '') { return str(m) }
  m = match(s, '^(.*?)\\.html$', 1)
  if (str(m) != '') { return str(m) }
  return s
}

fn sdPages(html, cur) {
  let h = str(html)
  let tot = match(h, '第\\(([0-9]+)/([0-9]+)\\)页', 2)
  let now = match(h, '第\\(([0-9]+)/([0-9]+)\\)页', 1)
  if (str(tot) == '' || str(now) == '') { return '' }
  let total = int(str(tot), 0)
  let curp = int(str(now), 0)
  if (total <= 1 || curp >= total || total > 60) { return '' }
  let base = sdPageBase(str(cur))
  let out = []
  let i = curp + 1
  while (i <= total) {
    out[len(out)] = base + '_' + str(i) + '.html'
    i = i + 1
  }
  return out
}

// ── 正文
// 容器叫 ReadAjax_content，但正文是服务端直出的，不需要执行 JS。
// 每页夹带「天才一秒记住本站地址…」「亲,记得收藏网址哟」「推荐…新书:<a>…</a>」『加入书签』。
// 用一条 match 一次取出容器内容，不用 substring（参数语义在表达式层不稳）。
fn sdText(html) {
  let h = str(html)
  let s = str(match(h, 'id="chaptercontent"[^>]*>([\\s\\S]*?)</div>', 1))
  if (s == '') { return '' }
  s = replace(s, '推荐[^<>]{0,12}大神[^<>]{0,20}[:：][\\s\\S]{0,200}?</a>', '', 'g')
  s = replace(s, '天才一秒记住本站地址[^<>]{0,90}', '', 'g')
  s = replace(s, '亲[，,]?记得收藏网址[^<>]{0,40}', '', 'g')
  s = replace(s, '第[0-9]+章[^<>]{0,60}?第\\([0-9]+/[0-9]+\\)页[，,]?点击下一页继续阅读[。.]?', '', 'g')
  s = replace(s, '『加入书签[^』]{0,24}』', '', 'g')
  s = replace(s, '(<br\\s*/?>[ \\t\\n\\r]*){2,}', '\n', 'g')
  s = replace(s, '<br\\s*/?>', '\n', 'g')
  s = replace(s, '</p>', '\n', 'g')
  s = replace(s, '<[^>]*>', '', 'g')
  s = replace(s, '\r', '', 'g')
  s = htmlDecode(s)
  s = replace(s, '&nbsp;', ' ', 'g')
  s = replace(s, '[ \\t]*第[0-9]+章[^\\n]{0,60}?第\\([0-9]+/[0-9]+\\)页[ \\t]*', '', 'g')
  s = replace(s, '[ \\t]+', ' ', 'g')
  s = replace(s, '\\n[ \\t]+', '\n', 'g')
  s = replace(s, '(\\n[ \\t]*){2,}', '\n', 'g')
  // 开头是「序章第(1/2)页」这种标题+分页标记；上面那条只认「第N章」，这里整行删
  s = replace(s, '^[ \\t]*[^\\n]*?第\\([0-9]+/[0-9]+\\)页[ \\t]*\\n?', '', 'gm')
  return trim(s)
}

