// 目录：站点 #list 里有两个 <dt>（① 最新章节预览倒序 ② 正文完整正序）。
// 原生不能跑 JS，用「切出 #list → 按 <dt 切分取最后一段 → 截到 </dl> → 取 dd 里的链接」复刻。
// 关键：正文那个 dt 里还夹着一个「TXT下载」的绝对链接，若用 replace+split 拼行会被它污染；
// 所以 href 与标题都只用 /xiaoshuo/<书号>/<章号>.html 这个相对锚点匹配，两次 matchAll 天然对齐。
fn aileToc(html) {
  let h = str(html)
  let i = indexOf(h, 'id="list"')
  let s = i >= 0 ? substring(h, i, len(h)) : h
  let parts = split(s, '<dt')
  let tail = str(parts[len(parts) - 1])
  let j = indexOf(tail, '</dl>')
  if (j >= 0) { tail = substring(tail, 0, j) }
  let hrefs = matchAll(tail, '<a href="(/xiaoshuo/[0-9]+/[0-9]+[.]html)"', 1)
  let titles = matchAll(tail, 'href="/xiaoshuo/[0-9]+/[0-9]+[.]html"[^>]*>([^<]*)</a>', 1)
  let out = []
  let k = 0
  while (k < len(hrefs) && k < len(titles)) {
    let t = trim(str(titles[k]))
    if (t != '') { push(out, { title: t, url: str(hrefs[k]) }) }
    k = k + 1
  }
  return out
}

// 目录/正文的分页地址拼绝对路径（结果是 // 开头时补 https:）
fn hhAbs(u, base) {
  let s = str(u)
