  if (match(s, '^(https?://)', 1) != '') { return s }
  if (match(s, '^//', 1) != '') { return 'https:' + s }
  if (match(s, '^/', 1) != '') { return str(base) + s }
  return str(base) + '/' + s
}
// 搜索结果的书名带 [类别] 前缀，取方括号里的类别；没有方括号返回空
