// ===== 幽香书房 原生书源 函数库 v6（2026-10-16 抗 WAF 版）=====

// ── 0. 接口主机归一 ─────────────────────────────────────────────────────
// 目录接口是 POST，而裸域/http 会把它 301 成 GET（请求体丢失）→ 403。
fn yxApiRoot(host) {
  let h = replace(str(host), '^https?://', '', '')
  h = replace(h, '^www\\.', '', '')
  h = replace(h, '/[\\s\\S]*$', '', '')
  return 'https://www.' + h
}

// ── 1. 目录接口加密 ─────────────────────────────────────────────────────
// ⚠ 站点会**轮换 AES 密钥**（封装在 /templates/js/<32位hash>.js 里，文件名随 hash 变）。
//   旧密钥 = 服务端解密失败 = HTTP 403 {"code":-1,"msg":"Error"} —— 这不是风控！
//   所以 key/iv 改成从站点自己的脚本现取（cache.site/jsName/js），取不到才用下面的常量兜底。
fn yxAes(plain, key, iv) {
  let k = str(key)
  let v = str(iv)
  if (len(k) != 32) { k = 'SatdUcOtSLhcPw2v64B8oRToIZZt0Hdr' }
  if (len(v) != 16) { v = '8075311411457704' }
  return urlencode(bytesBase64(encrypt('AES/CBC/PKCS5Padding', plain, k, v)))
}

// 探针请求体（书码由首页现取；key/iv 由密钥脚本现取）
fn yxProbeBody(bid, key, iv) {
  let b = yxOrBid(bid)
  return 'data=' + yxAes('{\"id\":\"' + b + '\",\"page\":1}', key, iv)
}

// 首页里第一个书级链接（/book/XXXX.html）→ 探针书码，永不过期
fn yxFirstBid(html) {
  let m = match(str(html), '/book/([A-Za-z0-9]+)\\.html', 1)
  if (m == null) { return '' }
  return str(m)
}
fn yxOrBid(bid) {
  let s = trim(str(bid))
  if (len(s) < 2 || len(s) > 16) { return 'QBXF' }
  return s
}

// 接口地址：带上 &b=<书码>，让每本书的地址彼此不同
// （否则「探针」和「目录第 1 页」的 URL 完全一样，真机引擎会把后者当成重复地址过滤掉 → 少 100 章）
fn yxApiUrl(api, bid, page) {
  return str(api) + '/index.php?action=loadChapterPage&i=' + str(page) + '&b=' + str(bid)
}
// 前 100 章由详情页内嵌目录直接给出（真实名、零风险），所以接口只需要从第 2 页开始
fn yxFront(html, bid) {
  let t = yxTotal(html, bid)
  if (t > 100) { return 100 }
  return t
}

// 目录请求体
fn yxBody(bid, page, key, iv) {
  return 'data=' + yxAes('{\"id\":\"' + str(bid) + '\",\"page\":' + str(page) + '}', key, iv)
}

// ── 1b. 密钥自愈用的三个小工具 ──────────────────────────────────────────
// 'a|b' 取第 idx 段
fn yxSplit(s, idx) {
  let parts = split(str(s), '|')
  return str(default(parts[int(str(idx), 0)], ''))
}
// 详情页里引用的 32 位 hash 脚本名（站点的 AES 封装就在这个文件里）
fn yxJsName(html) {
  let m = match(str(html), '/templates/js/([A-Za-z0-9]{32})', 1)
  if (m == null) { return '' }
  return str(m)
}
// 从密钥脚本里取 "key|iv"
fn yxKeyIv(js) {
  let s = str(js)
  let k = match(s, 'AESCrypt\\(.([A-Za-z0-9]{32}).', 1)
  let v = match(s, 'parse\\(.([0-9]{16}).\\)', 1)
  if (k == null || v == null) { return '' }
  let ks = str(k)
  let vs = str(v)
  if (len(ks) != 32 || len(vs) != 16) { return '' }
  return ks + '|' + vs
}

// ── 2. 目录分页页数（<option value="N">1-100章</option> 的个数）────────────
fn yxPageCount(html) {
  let n = len(matchAll(str(html), '<option value="[0-9]+">', 0))
  if (n < 1) { n = 1 }
