// ── 2b. <option> 里最大的结束章号（仅作最后兜底，是上界）────────────────
fn yxOptEnd(html) {
  let mx = 0
  for s in matchAll(str(html), '<option value="[0-9]+">([^<]*)</option>', 1) {
    let m = match(str(s), '-([0-9]+)\\s*章', 1)
