// 注意：站点的「目录<span>（N章）」对一部分书写成 0 章（实测 QOPB/IPKM），
//       只认它就会退化成「只有 100 章」—— 这正是用户反馈的那个 bug。
fn yxPageMax(html, bid) {
  let b = str(bid)
  if (b == '') { return 0 }
  let mx = 0
  for s in matchAll(str(html), '/book/' + b + '-([0-9]+)\\.html', 1) {
    let n = int(str(s), 0)
    if (n > mx) { mx = n }
  }
  return mx
}

// ── 3. 总章数：多来源取最大（全部来自同一个详情页，零额外请求）──────────
fn yxTotal(html, bid) {
  let h = str(html)
  let t = 0
  // ① 目录<span>（N章）
  let sp = match(h, '目录<span>（\\s*([0-9]+)\\s*章', 1)
  if (sp != null) { t = int(str(sp), 0) }
  // ② og:novel:latest_chapter_url 的章号（部分书没有这个 meta）
  let og = match(h, 'og:novel:latest_chapter_url"[^>]*content="[^"]*?-([0-9]+)\\.html', 1)
  if (og != null) {
    let n = int(str(og), 0)
