  }
  // ③ 全页同名书链接最大章号（最可靠，span 为 0 的书也靠它）
  let pm = yxPageMax(h, bid)
  if (pm > t) { t = pm }
  // ④ 三个都没有 → 用 <option> 上界兜底（宁多勿少）
  if (t < 1) { t = yxOptEnd(h) }
  return t
}

// ── 3b. 接口要抓多少页：<option> 页数与「按总章数算出的页数」取大 ─────────
fn yxTocPages(html, bid) {
  let p = yxPageCount(html)
  let total = yxTotal(html, bid)
  let need = 0
  let c = 0
  while (c < total && need < 200) {
    need = need + 1
    c = c + 100
  }
  if (need > p) { p = need }
  if (p < 1) { p = 1 }
  if (p > 200) { p = 200 }
  return p
}

