// ── 6. 降级路径：用详情页自己把整本目录铺出来（零额外请求）───────────────
// 名字来源（同一页）：<ul id="ul_all_chapters"> 的 1..100 章 + 头部「最新章节」
// 的最后 20 章（真实标题）。中间取不到的章号给「第N章」占位，URL 一律按
// /book/{书码}-{章号}.html 构造 —— 站点保证该形状可直接打开。
// ⚠ 必须限定同名书（/book/{bid}-N.html），否则「相关推荐」的其它书会混进来。
fn yxTocFill(html, bid, root, total) {
  let b = str(bid)
  if (b == '') { return [] }
  let base = str(root)
  if (!endsWith(base, '/')) { base = base + '/' }
  let lim = int(str(total), 0)
  if (lim < 1) { return [] }
  let titles = list(lim + 1, '')
  for c in split(str(html), '<a ') {
    let cs = str(c)
    let hf = match(cs, 'href="/book/' + b + '-([0-9]+)\\.html"', 1)
    if (hf != null) {
      let no = int(str(hf), 0)
      if (no > 0 && no <= lim) {
        let tag = match(cs, '^[^>]*>', 0)
        let ti = null
        if (tag != null) { ti = match(str(tag), 'title="([^"]*)"', 1) }
        if (ti == null) { ti = match(cs, '>([^<]*)</a>', 1) }
        let t = trim(str(ti))
        if (t != '') { titles[no] = t }
      }
    }
  }
  let out = []
  let k = 0
  let c = 1
  while (c <= lim) {
    let nm = titles[c]
    if (nm == null || nm == '') { nm = '第' + c + '章' }
