// 笔趣阁 · 双线路合并
// vars.line: 'bqquge...' | 'byqg...'（取前缀判断）
function bqLine(ctx) {
  var v = String((ctx && ctx.vars && ctx.vars.line) || 'bqquge');
  return v.indexOf('byqg') === 0 ? 'byqg' : 'bqquge';
}
function bqHost(line) {
  return line === 'byqg' ? 'https://www.byqg.cc' : 'https://www.bqquge.org';
}
function bqAbs(line, u) {
  var s = String(u || '');
  if (!s) return '';
  if (/^https?:/i.test(s)) return s;
  return bqHost(line) + (s.charAt(0) === '/' ? s : '/' + s);
}
function bqText(v) {
  if (v == null) return '';
  if (Array.isArray(v)) v = v.length ? v[0] : '';
  var s = String(v == null ? '' : v);
  // 去掉可能夹带的标签，再压空白
  s = s.replace(/<[^>]*>/g, '');
  return s.replace(/\s+/g, ' ').trim();
}

// ---------- 列表解析（搜索与发现共用）----------
function bqCardByqg(c, line) {
  var name = bqText(native.sel('@css:.bookname a@text', c));
  var href = native.sel('@css:.bookname a@href', c);
  if (!name || !href) return null;
  var auths = native.selAll('@css:.author@text', c);
  var author = '', words = '';
  auths.forEach(function (a) {
    var t = bqText(a);
    if (t.indexOf('作者') === 0) author = t.replace(/^作者[:：]\s*/, '');
    else if (t.indexOf('字数') === 0) words = t.replace(/^字数[:：]\s*/, '');
  });
  return {
    name: name,
    author: author,
    bookUrl: bqAbs(line, href),
    lastChapter: bqText(native.sel('@css:.cat a@text', c)),
    wordCount: words
  };
}

function bqCardBqquge(c, line) {
  var name = bqText(native.sel('@css:.itemtxt h3 a@text', c));
  var href = native.sel('@css:.itemtxt h3 a@href', c);
  if (!name || !href) return null;
  var paras = native.selAll('@css:.itemtxt p@html', c);
  var status = '', kind = '', author = '';
  paras.forEach(function (p) {
    // 第 1 个 p 是「状态 + 分类」两个 span，第 2 个 p 是作者链接
    var sp = native.selAll('@css:span@text', p);
    if (sp.length >= 2) { status = bqText(sp[0]); kind = bqText(sp[1]); }
    var at = native.sel('@css:a@text', p);
    if (at && String(at).indexOf('作者') >= 0) author = String(at).replace(/^作者[:：]\s*/, '');
  });
  var chg = native.selAll('@css:.itemtxt ul li a@text', c);
  return {
    name: name,
    author: bqText(author),
    bookUrl: bqAbs(line, href),
    coverUrl: bqAbs(line, native.sel('@css:.item > a img@src', c)),
    status: status,
    kind: kind,
    lastChapter: chg.length ? bqText(chg[0]) : ''
  };
}

function bqListByqg(h, line) {
  var out = [];
  native.selAll('@css:.bookbox .bookinfo@html', h).forEach(function (c) {
    var it = bqCardByqg(c, line);
    if (it) out.push(it);
  });
  return out;
}

function bqListBqquge(h, line) {
  var out = [];
  native.selAll('@css:.item@html', h).forEach(function (c) {
    var it = bqCardBqquge(c, line);
    if (it) out.push(it);
  });
  return out;
}

// ---------- 发现 ----------
// 总页数：bqquge 是 <span>1/442</span>，byqg 是 <em id="pagestats">1/60</em>
function bqMaxPage(h) {
  var s = String(h || '');
  var m = s.match(/id="pagestats">\s*\d+\s*\/\s*(\d+)/);
  if (m) return Number(m[1]);
  m = s.match(/<span>\s*\d+\s*\/\s*(\d+)\s*<\/span>/);
  if (m) return Number(m[1]);
  return 0;
}

function bqExplore(ctx) {
  ctx = ctx || {};
  var line = bqLine(ctx);
  var p = Number(ctx.page || 1) || 1;
  var u = String(ctx.url || '');
  if (!u) return [];
  // 菜单地址里可能残留 {{page}} / {{source.url}}，补一次
  u = u.replace(/\{\{\s*page\s*\}\}/g, String(p));
  u = u.replace(/\{\{\s*source\.url\s*\}\}/g, bqHost(line));
  // bqquge 的第 1 页没有 /N 后缀（实测 /paihang/1 是 404，/paihang 才是第 1 页）
  if (line !== 'byqg') {
    var m1 = u.match(/\/(\d+)\/?$/);
    if (m1 && Number(m1[1]) <= 1) u = u.replace(/\/\d+\/?$/, '');
  }
  if (!/^https?:/i.test(u)) u = bqAbs(line, u);
  var r = http.get(u, { timeout: 25000 });
  // 翻过头时站点会 302 到末页（bqquge）或照常返回末页内容（byqg），
  // 这里返回空数组让宿主停下，别抛错（不然用户翻到底就弹错误）
  if (!r.ok) {
    if (p > 1) return [];
    throw new Error('分类请求失败 HTTP ' + r.status);
  }
  var h = r.body;
  var max = bqMaxPage(h);
  if (p > 1 && max > 0 && p > max) return [];
  return line === 'byqg' ? bqListByqg(h, line) : bqListBqquge(h, line);
}

// ---------- 搜索 ----------
function bqSearch(ctx) {
  var line = bqLine(ctx);
  var key = String((ctx && ctx.key) || '');
  if (!key) return [];
  var host = bqHost(line);
  var url = line === 'byqg'
    ? host + '/search/' + encodeURIComponent(key) + '.html'
    : host + '/so/' + encodeURIComponent(key);
  var r = http.get(url, { timeout: 20000 });
  if (!r.ok) throw new Error('搜索失败 HTTP ' + r.status);
  var h = r.body;
  return line === 'byqg' ? bqListByqg(h, line) : bqListBqquge(h, line);
}

// ---------- 详情 ----------
function bqDetail(ctx) {
  var line = bqLine(ctx);
  var bu = String((ctx.book && (ctx.book.bookUrl || ctx.book.tocUrl)) || '');
  var r = http.get(bu, { timeout: 20000 });
  if (!r.ok) throw new Error('详情失败 HTTP ' + r.status);
  var h = r.body;
  var o = { bookUrl: bu };
  function pick(sel) { return bqText(native.sel(sel, h)); }
  function after(label) {
    var m = h.match(new RegExp(label + '[:：]\\s*([^<\\n]{1,40})'));
    return m ? m[1].trim() : '';
  }
  if (line === 'byqg') {
    o.name = pick('@css:h1.booktitle@text');
    o.author = pick('@css:p.booktag a.red@text');
    o.kind = pick('@css:p.booktag a.blue@text');
    o.status = pick('@css:p.booktag span.red@text');
    var blues = native.selAll('@css:p.booktag span.blue@text', h);
    o.wordCount = bqText(blues[0]);
    o.intro = pick('@css:p.bookintro@text');
    o.lastChapter = pick('@css:a.bookchapter@text');
    o.updateTime = pick('@css:p.booktime@text').replace(/^更新时间[:：]\s*/, '');
    var m = String(bu).match(/\/book\/([^\/.]+)\.html/);
    o.tocUrl = m ? bqHost(line) + '/chapter/' + m[1] + '.html' : bu;
  } else {
    o.name = pick('@css:h1@text');
    o.author = pick('@css:.booktxt p a@text').replace(/^作者[:：]\s*/, '');
    o.kind = after('类别').replace(/小说$/, '');
    o.status = after('状态');
    o.wordCount = after('字数');
    o.updateTime = after('更新');
    o.intro = pick('@css:.des@text');
    var newc = native.selAll('@css:.newest h3 a@text', h);
    o.lastChapter = bqText(newc[0]);
    o.tocUrl = bu;
  }
  o.type = 'text';
  return o;
}

// ---------- 目录 ----------
function bqToc(ctx) {
  var line = bqLine(ctx);
  var bu = String((ctx.book && (ctx.book.tocUrl || ctx.book.bookUrl)) || (ctx.baseUrl || ''));
  var r = http.get(bu, { timeout: 25000 });
  if (!r.ok) throw new Error('目录失败 HTTP ' + r.status);
  var h = r.body;
  var out = [];
  if (line === 'byqg') {
    var links = native.selAll('@css:#allchapter dd a@html', h);
    links.forEach(function (a) {
      var t = bqText(native.sel('@css:@text', a));
      var href = native.sel('@css:@href', a);
      if (!t || !href || t.indexOf('查看全部') >= 0) return;
      out.push({ title: t, url: bqAbs(line, href) });
    });
  } else {
    native.selAll('@css:#list li a@html', h).forEach(function (a) {
      var t = bqText(native.sel('@css:@text', a));
      var href = native.sel('@css:@href', a);
      if (!t || !href) return;
      out.push({ title: t, url: bqAbs(line, href) });
    });
  }
  if (!out.length) throw new Error('目录为空：站点结构可能已变，或该书已下架');
  return out;
}

// ---------- 正文 ----------
function bqContent(ctx) {
  var line = bqLine(ctx);
  var u = String((ctx.chapter && ctx.chapter.url) || '');
  if (!u) throw new Error('缺少章节地址');
  var r = http.get(u, { timeout: 20000 });
  if (!r.ok) throw new Error('正文失败 HTTP ' + r.status);
  var h = r.body;
  var sel = line === 'byqg' ? '@css:#content p@text' : '@css:.con p@text';
  var ps = native.selAll(sel, h);
  var lines = [];
  ps.forEach(function (p) {
    var t = bqText(p);
    if (!t) return;
    if (/^（本章未完|^一秒记住|^请收藏本站|^-{6,}$|看最新章节|今日一章/.test(t)) return;
    if (/(请收藏本站|www\.[a-z]+\.com|一秒记住)/.test(t) && t.length < 60) return;
    lines.push(t);
  });
  // 首行常重复章节标题（bqquge 的 <p> 就是标题本身），去掉
  var title = bqText((ctx.chapter && ctx.chapter.title) || '');
  if (lines.length && title && lines[0].replace(/\s/g, '') === title.replace(/\s/g, '')) lines.shift();
  var text = lines.join('\n');
  if (!text) throw new Error('这一章正文为空，请从目录换一章');
  return { text: text };
}

