function qmHeaders() {
  const headers = {};
  Object.keys(QM_HEADER_BASE).forEach(key => {
    if (String(QM_HEADER_BASE[key]) !== '') headers[key] = QM_HEADER_BASE[key];
  });
  headers.sign = qmSign(headers);
  return headers;
}

function qmQs(params) {
  return Object.keys(params).map(k => k + '=' + encodeURIComponent(params[k])).join('&');
}

function qmApi(base, path, params) {
  const query = Object.assign({}, params, { sign: qmSign(params) });
  return base + path + '?' + qmQs(query);
}

function qmRequest(base, path, params) {
  const url = qmApi(base, path, params);
  const headers = qmHeaders();
  const res = http.get(url, { headers, timeout: 15000 });
  if (!res.ok) throw new Error('七猫接口请求失败：HTTP ' + res.status + (res.error ? ' ' + res.error : ''));
  const data = res.json();
  if (data.errors && data.errors.details) {
    throw new Error('七猫接口错误：' + data.errors.details + '（' + (data.errors.code || '未知') + '）');
  }
  return data;
}

function qmBookId(ctx) {
  const kept = ctx.book && ctx.book.vars ? String(ctx.book.vars.bookId || '') : '';
  if (kept) return kept;
  const url = String((ctx.book && ctx.book.bookUrl) || ctx.baseUrl || '');
  let m = url.match(/[?&](?:bookId|book_id|id)=([0-9]+)/);
  if (m) return m[1];
  m = url.match(/qm:\/\/([0-9]+)\//);
  if (m) return m[1];
  m = url.match(/page\/([0-9]+)/);
  return m ? m[1] : '';
}

function qmBookUrl(id) {
  const ip = qmImei();
  return 'https://api-bc.wtzw.com/api/v4/book/detail?id=' + encodeURIComponent(String(id)) +
    '&imei_ip=' + encodeURIComponent(ip) + '&teeny_mode=0';
}

function qmBookFields(book) {
  const words = Number(book.words_num || 0);
  const wordText = words >= 10000 ? (words / 10000).toFixed(1) + '万字' : (words ? String(words) + '字' : '');
  const tags = Array.isArray(book.book_tag_list)
    ? book.book_tag_list.map(x => String(x.title || '')).filter(Boolean).join(',')
    : '';
  const pub = String(book.type) === '2' || String(book.category_type) === 'publish' ? '出版' : '';
  const kind = [pub, book.category1_name, book.category2_name, tags].filter(Boolean).join(',');
  return {
    name: String(book.title || ''),
    author: String(book.author || ''),
    kind: kind,
    intro: String(book.intro || ''),
    coverUrl: String(book.image_link || '').replace(
      /_[0-9]+x[0-9]+(?=\.(?:jpe?g|png|webp)(?:[?#]|$))/i,
      '_360x480'
    ),
    wordCount: wordText,
    lastChapter: String(book.latest_chapter_title || ''),
    updateTime: book.update_time ? native.formatDate(Number(book.update_time) * 1000, 'yyyy-MM-dd HH:mm') : '',
    status: String(book.is_over) === '1' ? '完结' : '连载',
    type: 'text',
    bookUrl: qmBookUrl(book.id)
  };
}

