function qmDetail(ctx) {
  const id = qmBookId(ctx);
  if (!id) throw new Error('缺少七猫书籍 ID');
  const data = qmRequest(QM_BC, '/api/v4/book/detail', {
    id: id,
    imei_ip: qmImei(),
    teeny_mode: '0'
  });
  const book = data.data && data.data.book;
  if (!book) throw new Error('七猫详情接口未返回书籍');
  if (String(book.id || '') !== id) throw new Error('七猫详情接口返回了不匹配的书籍');
  const fields = qmBookFields(book);
  fields.bookUrl = qmBookUrl(id);
  keep('bookId', id);
  return fields;
}

function qmToc(ctx) {
