function qmContent(ctx) {
  const url = String((ctx.chapter && ctx.chapter.url) || ctx.url || '');
  const m = url.match(/^qm:\/\/([0-9]+)\/([^/]+)\/([01])(?:\/([0-9a-f]*))?$/);
  if (!m) throw new Error('无法解析七猫章节地址：' + url);
  const params = { id: m[1], chapterId: m[2] };
  if (m[3] === '1') params.reader_agent = '1';
  const data = qmRequest(QM_KS, '/api/v1/chapter/content', params);
  if (!data.data || !data.data.content) throw new Error('七猫正文接口未返回内容');
  const raw = native.base64Bytes(data.data.content);
  const plain = native.decrypt('AES/CBC/PKCS5Padding', raw.slice(16), QM_AES, raw.slice(0, 16));
  return native.fromBytes(plain);
}
const QM_CHANNELS = { male: '1', female: '2', publish: '3' };

