function qmExplore(ctx) {
  const u = String((ctx && ctx.url) || "");
  let m = /(?:[?&]|^)category_id=([^&]*)/.exec(u);
  if (m) {
    const categoryId = decodeURIComponent(m[1] || "");
    m = /(?:[?&]|^)category_type=([^&]*)/.exec(u);
    const categoryType = m ? decodeURIComponent(m[1]) || "0" : "0";
    m = /(?:[?&]|^)gender=([^&]*)/.exec(u);
    const gender = m ? decodeURIComponent(m[1]) || "1" : "1";
    const channel = gender === "2" ? "female" : (gender === "3" ? "publish" : "male");
    return qmExplorePage(channel, categoryId, categoryType, ctx);
  }
  const parts = u.split("|");
  let channel = qmChannelCode(parts[0]);
  let categoryId = parts[1] || "";
  let categoryType = parts[2] || "0";
  if (parts[0] === "channel") {
    channel = qmChannelCode(categoryId);
