    categoryType = "0";
  }
  if (!categoryId) {
    const first = qmCategoryMenu(channel).find(x => x.url && x.url.indexOf(channel + "|") === 0);
    if (!first) throw new Error("七猫发现频道没有可用分类：" + channel);
    const fallback = first.url.split("|");
    categoryId = fallback[1];
    categoryType = fallback[2] || "0";
  }
  return qmExplorePage(channel, categoryId, categoryType, ctx);
}function qmExplorePage(channel, categoryId, categoryType, ctx) {
  const page = Number((ctx && ctx.page) || 1);
