  }[String(vs.words || '全部')] || '-99';
  const sort = {
    '更新': '1',
    '评分': '2',
    '新书': '3'
  }[String(vs.sort || '热度')] || '0';
  const params = {
    category_id: String(categoryId),
    category_type: String(categoryType || '0'),
    gender: QM_CHANNELS[channel] || QM_CHANNELS.male,
    book_preference: '1',
    read_preference: '0',
    from: '4',
    need_filters: '1',
    page: String(page),
    over: over,
    words: words,
    sort: sort,
    book_privacy: '1'
  };
  const data = qmRequest(QM_BC, '/api/v5/category/get-list', params);
  const books = ((data.data && data.data.books) || []).slice(0, 10);
  const urls = books.map(book => qmApi(QM_BC, '/api/v4/book/detail', {
    id: String(book.id),
    imei_ip: qmImei(),
    teeny_mode: '0'
  }));
  const details = http.all(urls.map(url => ({ url: url, headers: qmHeaders() })));
  return books.map((book, index) => {
    let full = book;
    if (details[index] && details[index].ok) {
      try {
        const item = details[index].json();
        if (item.data && item.data.book) full = item.data.book;
      } catch (e) {
        full = book;
      }
    }
    return Object.assign({}, qmBookFields(full), {
      bookUrl: qmBookUrl(book.id)
    });
  });
}

/* ===================== 评论模块（v28） =====================
 * 相比 v29 的三处改进：
 * 1) 行索引与正文同源：qmCmIndex 在 content 阶段对"即将返回的正文"算表，
 *    段评阶段只查表，永不重算 md5 —— 规避 para.text 被截 90 字 + 行号漂移。
 * 2) 孤儿评论兜底：pid 对不上任何当前段落时（章节被作者改过，实测约 2.7%），
 *    不丢弃，转入「其他段评」入口。
 * 3) 签名单一实现：qmCmSign 一个函数管所有评论接口。
 * 评论任一步失败都不影响正文。
 */
const QM_CMNT = 'https://api-cmnt.wtzw.com';
const QM_CM_HEAD = {
  'app-version': '80400', 'application-id': 'com.kmxs.reader',
  'channel': 'qm-guanfang_lf', 'is-white': '0', 'net-env': '1',
  'platform': 'android', 'reg': '0'
};
// 签名必须覆盖「顶层 headers 与阶段 headers 合并后真正发出去」的字段。
// 顶层 headers 带 reg=0；空值头（AUTHORIZATION）引擎不发，故不参与签名。
const QM_CM_ORDER = ['app-version', 'application-id', 'channel',
  'is-white', 'net-env', 'platform', 'reg'];

function qmCmSign(obj) {
  return native.md5(Object.keys(obj).sort().map(function (k) {
    return k + '=' + obj[k];
  }).join('') + QM_KEY);
}

var QM_CM_HDR_SIGN = '';
function qmCmHeaderSign() {
  if (QM_CM_HDR_SIGN) { return QM_CM_HDR_SIGN; }
  QM_CM_HDR_SIGN = native.md5(QM_CM_ORDER.map(function (k) {
    return k + '=' + QM_CM_HEAD[k];
  }).join('') + QM_KEY);
  return QM_CM_HDR_SIGN;
}

function qmCmIds(url) {
  var m = String(url || '').match(/^qm:\/\/([0-9]+)\/([^\/]+)(?:\/[01])?(?:\/([0-9a-f]*))?/);
  if (!m) { return { bid: '', cid: '', md5: '' }; }
  return { bid: m[1], cid: m[2], md5: m[3] || '' };
}

function qmCmForm(params) {
  var body = Object.keys(params).sort().map(function (k) {
    return k + '=' + encodeURIComponent(String(params[k]));
  }).join('&');
  return body + '&sign=' + qmCmSign(params);
}

/* 行索引表：正文阶段算一次。idx=[pid...]，map={pid:行号} */
function qmCmIndex(text) {
  var out = { idx: [], map: {}, total: 0 };
  try {
    var lines = String(text == null ? '' : text).split('\n');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      if (!line || !line.trim()) { continue; }
      var pid = native.md5(line).slice(0, 8);
      out.map[pid] = out.total;
      out.idx.push(pid);
      out.total++;
    }
  } catch (e) {}
  return out;
}

/* counts：键是段落行号，值是条数。查表，不重算 */
function qmCmCounts(index, stats) {
  var out = {};
  try {
    var chs = (stats && stats.data && stats.data.chapters) || [];
    var bubbles = (chs[0] || {}).bubbles || [];
    for (var i = 0; i < bubbles.length; i++) {
      var b = bubbles[i] || {};
      var cnt = Number(b.c || 0);
      if (!(cnt > 0)) { continue; }
      var line = index.map[b.p];
      if (line === undefined || line === null) { continue; }
      out[line] = cnt;
    }
  } catch (e) {}
  return out;
}

/* 孤儿段评：pid 对不上当前正文 → 不丢，转成可点入口 */
function qmCmOrphans(index, stats) {
  var out = [];
  try {
    var chs = (stats && stats.data && stats.data.chapters) || [];
    var bubbles = (chs[0] || {}).bubbles || [];
    for (var i = 0; i < bubbles.length; i++) {
      var b = bubbles[i] || {};
      var cnt = Number(b.c || 0);
      if (!(cnt > 0)) { continue; }
      var line = index.map[b.p];
      if (line !== undefined && line !== null) { continue; }
      out.push({ pid: b.p, count: cnt });
    }
  } catch (e) {}
  return out;
}

function qmCmPidByIndex(index, i) {
