function qmCmItems(resp) {
  var out = [];
  try {
    var d = (resp && resp.data) || {};
    var zones = ['hot_zone', 'time_zone'];
    for (var z = 0; z < zones.length; z++) {
      var list = (d[zones[z]] || {}).comment_list || [];
      for (var i = 0; i < list.length; i++) {
        if (list[i]) { out.push(list[i]); }
      }
    }
  } catch (e) {}
  return out;
}

function qmCmTotal(resp, fallback) {
  try {
    var d = (resp && resp.data) || {};
    var tz = d.time_zone || {}, hz = d.hot_zone || {};
    var n = Number(tz.comment_count || hz.comment_count || 0);
    if (n > 0) { return n; }
  } catch (e) {}
  return Number(fallback || 0);
}

