/* ---------- 双流合并：hot=0(最新10) + hot=1(热门10)，去重后最多 20 条 ----------
 * 依据：/paragraph/first 与 /chapter-comment/first 都只返 10 条，
 *       但 hot 参数切换后返回完全不同的一批（实测重复 0）。
 *       页面 fetch 预算最多 3 个请求，故取 2 个刚好。
 */
function qmCmMerge(a, b) {
  var out = [], seen = {};
  var lists = [qmCmItems(a), qmCmItems(b)];
  for (var l = 0; l < lists.length; l++) {
    var arr = lists[l];
    for (var i = 0; i < arr.length; i++) {
      var x = arr[i] || {};
      var key = String(x.comment_id || x.content_id || (x.user_info || {}).uid + '|' + x.content);
      if (seen[key]) { continue; }
      seen[key] = 1;
      out.push(x);
    }
  }
  return out;
}

// 两路合计条数（用于标题显示"共 N 条"）
function qmCmMergeTotal(a, b, fallback) {
  var n = qmCmItems(a).length + qmCmItems(b).length;
  if (n > 0) { return n; }
  return qmCmTotal(a, fallback);
