function fixMiaoqu(bytes, ctx) {
  if (bytes.length > 12 && bytes[0] === 0xFF && bytes[1] === 0xD8 && bytes[2] === 0xFF && bytes[3] === 0xE0 && bytes[8] === 0x57 && bytes[9] === 0x45 && bytes[10] === 0x42 && bytes[11] === 0x50) {
    const out = new Uint8Array(bytes.length);
    out[0] = 0x52;
    out[1] = 0x49;
    out[2] = 0x46;
    out[3] = 0x46;
    out.set(bytes.subarray(4), 4);
    return out;
  }
  return bytes;
}

