  var v = vget("imgSource", "");
  return v.indexOf("http") === 0 ? v.replace(/\/+$/, "") : "https://mwtuwu.cc";
}
function pageSize() {
  var n = parseInt(vget("pageSize", "30"), 10);
  if (!n || n < 10) n = 30;
  return n > 100 ? 100 : n;
}
function decryptOn() { return vget("decrypt", "0") === "1"; }

// ---------- 请求 ----------
function hdr() {
  return {
    "User-Agent": UA,
    "Accept-Language": "zh-CN,zh;q=0.9,zh-TW;q=0.8",
    "Accept": "application/json, text/javascript, */*; q=0.01",
    "X-Requested-With": "XMLHttpRequest",
    "Referer": host() + "/"
  };
}
function getJSON(path, what) {
  var r = http.get(host() + path, { headers: hdr() });
  var body = String((r && (r.body || r.content)) || "");
  var j = null;
  try { j = JSON.parse(body); } catch (e) { j = null; }
  if (!r || r.ok === false || r.status >= 400) {
    throw new Error((what || "接口") + " HTTP " + (r ? r.status : "?") + "：" + body.slice(0, 60));
  }
  if (!j) throw new Error((what || "接口") + " 返回非 JSON：" + body.slice(0, 60));
  if (j.code !== 200 && j.code !== 0) {
    throw new Error((what || "接口") + " code=" + j.code + " " + (j.msg || j.message || ""));
  }
  return j.data;
}
function postJSON(path, obj, what) {
  var h = hdr();
  h["Content-Type"] = "application/json;charset=UTF-8";
  var r = http.post(host() + path, JSON.stringify(obj), { headers: h });
  var body = String((r && (r.body || r.content)) || "");
  var j = null;
  try { j = JSON.parse(body); } catch (e) { j = null; }
  if (!r || r.ok === false || r.status >= 400) throw new Error((what || "列表") + " HTTP " + (r ? r.status : "?"));
  if (!j) throw new Error((what || "列表") + " 返回非 JSON：" + body.slice(0, 60));
  if (j.code !== 200) throw new Error((what || "列表") + " code=" + j.code);
  return j.data;
}

// ---------- 文本 / 图片 ----------
function unesc(s) {
  return String(s == null ? "" : s)
    .replace(/<br\s*\/?>/gi, "\n").replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&apos;/g, "'")
    .replace(/&ldquo;/g, "“").replace(/&rdquo;/g, "”").replace(/&lsquo;/g, "‘").replace(/&rsquo;/g, "’")
    .replace(/&hellip;/g, "…").replace(/&mdash;/g, "—").replace(/&ndash;/g, "–").replace(/&middot;/g, "·")
    .replace(/&#(\d+);/g, function (_, n) { return String.fromCharCode(parseInt(n, 10)); });
}
function fixImg(u) {
  u = String(u == null ? "" : u).trim();
  if (!u) return "";
  return u.replace("/en_images/", "/").replace(/^https?:\/\/[^\/]+/, imgBase());
}

// ---------- 探活（只回文字，不写 vars） ----------
// 并发探活：http.all 默认 8 并发，10 条线路约 200ms 出结果，不再串行 1 秒
function probeRace(pool) {
  var reqs = [];
  for (var i = 0; i < pool.length; i++) {
    reqs.push({ url: pool[i] + "/api/search?type=mh&page=1&pageSize=1&keyword=" + encodeURIComponent("漫"),
                headers: { "User-Agent": UA, "Accept": "application/json" }, timeout: 6000 });
  }
  var t0 = Date.now();
  var res = http.all(reqs, { concurrency: 8 });
  var cost = Math.max(1, Date.now() - t0);
  var out = [];
  for (var k = 0; k < pool.length; k++) {
    var r = res && res[k];
    var ok = false, why = "";
    try {
      var j = JSON.parse(String((r && (r.body || "")) || "{}"));
      ok = !!(r && r.ok !== false && r.status === 200 && j && j.code === 200);
      if (!ok) why = "HTTP" + (r ? r.status : "?");
    } catch (e) { ok = false; why = "非 JSON"; }
    // 并发下拿不到单条耗时，用整批耗时作上界（同一批发完的总时间），足够排序用
    out.push({ host: pool[k], ok: ok, ms: ok ? cost : 99999, why: why });
  }
  return out;
}
// 24 小时内的测速结果直接复用，进发现页不再每次探活
var LAT_KEY = "mw_lat";
function latCache() {
  var raw = cache.get(LAT_KEY);
  if (!raw) return null;
  try { var o = JSON.parse(raw); return (o && o.t > 0 && Date.now() - o.t < 86400000) ? o : null; } catch (e) { return null; }
}
function latSave(order, ms) {
  try { cache.put(LAT_KEY, JSON.stringify({ t: Date.now(), order: order, ms: ms })); } catch (e) {}
}

function probeOnce(h) {
  var t0 = Date.now();
  try {
    var r = http.get(h + "/api/search?type=mh&page=1&pageSize=1&keyword=" + encodeURIComponent("漫"),
                     { headers: { "User-Agent": UA, "Accept": "application/json" }, timeout: 6000 });
    var j = JSON.parse(String((r && (r.body || r.content)) || "{}"));
    if (r && r.status === 200 && j && j.code === 200) return { host: h, ok: true, ms: Date.now() - t0 };
    return { host: h, ok: false, ms: Date.now() - t0, why: "HTTP" + (r ? r.status : "?") + "/code" + (j ? j.code : "?") };
  } catch (e) {
    return { host: h, ok: false, ms: Date.now() - t0, why: e.message.slice(0, 40) };
  }
}
function probePool(pool) {
  var res = probeRace(pool);
  var live = 0;
  for (var i = 0; i < res.length; i++) if (res[i].ok) live++;
  // http.all 若不可用（老宿主/接口缺失）会整批失败，此时退回串行，逐条拿真实毫秒
  if (live > 0) return res;
  var out = [];
  for (var j = 0; j < pool.length; j++) out.push(probeOnce(pool[j]));
  return out;
}
// 选项脚本：活线路按耗时排前面，死的直接不出现；全部失败时返回原池，但**不**选死线
function hostOptions() {
  var c = latCache();
  if (c && c.order && c.order.length) {
    var cached = c.order.slice();
    if (cached.indexOf(host()) < 0) cached.unshift(host());
    return cached;
  }
  var res = probePool(HOSTS).filter(function (x) { return x.ok; });
  res.sort(function (a, b) { return a.ms - b.ms; });
  var list = res.map(function (x) { return x.host; });
  // 当前线路保底：探活抖动或偶发 5xx 时不至于把自己选掉
  if (list.indexOf(host()) < 0) list.unshift(host());
  // 国内网络下各线路延迟差 3-5 倍，测到更快就自动切过去（老线路明显更慢时切，避免抖动来回跳）
  var cur = host();
  var curMs = 0, bestMs = 0;
  for (var i = 0; i < res.length; i++) {
    if (res[i].host === cur) curMs = res[i].ms;
    if (!bestMs) bestMs = res[i].ms;
  }
  if (bestMs && res.length && res[0].host !== cur && (!curMs || curMs > bestMs * 1.6)) {
    vars.set("host", res[0].host);
  }
  latSave(list, null);
  return list.length ? list : HOSTS.slice(0, 1);
}
function imgOptions() {
  var res = probePool(IMGS).filter(function (x) { return x.ok; });
  res.sort(function (a, b) { return a.ms - b.ms; });
  var list = res.map(function (x) { return x.host; });
  if (list.indexOf(imgBase()) < 0) list.unshift(imgBase());
  return list.length ? list : IMGS.slice(0, 1);
}

// ---------- 字段映射 ----------
function mapItem(x) {
