    }
    var pg = (d && d.pagination) || {};
    totalPages = parseInt(pg.total_pages || 1, 10) || 1;
    if (page >= totalPages || list.length === 0) break;
    page++;
  }
  if (!imgs.length) throw new Error("该章没有取到图片（id=" + chid + "）");
  var html = [];
  for (var k = 0; k < imgs.length; k++) html.push('<p><img src="' + imgs[k] + '"/></p>');
  return {
    title: unesc((ctx.chapter && ctx.chapter.title) || ""),
