function actNewHost(ctx) {
  var seeds = ["https://mwmw.cc", "https://mwmw1.cc", "https://manwalu.cc", "https://manwa.xin"];
  var found = [];
  for (var i = 0; i < seeds.length; i++) {
    try {
      var r = http.get(seeds[i] + "/", { headers: { "User-Agent": UA } });
      var body = String((r && r.body) || "");
      var re = /atob\(\s*["']([A-Za-z0-9+/=]{8,})["']\s*\)/g;
      var m;
      while ((m = re.exec(body)) !== null) {
        var url = "";
        try { url = decodeURIComponent(escape(base64Decode(m[1]))); } catch (e) { url = ""; }
        if (url && url.indexOf("http") === 0 && found.indexOf(url) < 0) found.push(url);
      }
      var re2 = /https?:\/\/[a-z0-9-]+\.(?:cc|com|net|vip|xin)(?=[^a-z0-9-])/gi;
      while ((m = re2.exec(body)) !== null) {
        if (found.indexOf(m[0]) < 0) found.push(m[0]);
      }
    } catch (e) { /* 种子站打不开就算了 */ }
  }
  found = found.filter(function (x) { return /^https?:\/\/[a-z0-9.-]+(:\d+)?$/i.test(x); });
  if (!found.length) return "没解析出新域名：\n" + seeds.join("\n") + "\n（可在电脑上跑 manwa_scan.py 更新线路池）";
  var live = [];
  for (var k = 0; k < found.length; k++) {
    if (!/^https?:\/\/[a-z0-9.-]+(:\d+)?$/i.test(found[k])) continue;
    var x = probeOnce(found[k]);
    if (x.ok) live.push(found[k]);
  }
  return "解析到 " + found.length + " 个候选，可用 " + live.length + " 个：\n" + live.join("\n");
}
