// ===== 精确延迟探测（国内直连口径）=====
// probeRace 并发拿不到单条毫秒，只能用整批总时长糊弄排序。
// 这里改成：并发筛可用 → 串行精确测延迟。10 条线路串行约 1 秒，换来真实数据。
function hostProbeExact(h, timeoutMs) {
  var t0 = Date.now();
  try {
    var r = http.get(h + "/api/search?type=mh&page=1&pageSize=1&keyword=" + encodeURIComponent("漫"),
      { headers: { "User-Agent": UA, "Accept": "application/json" }, timeout: timeoutMs || 6000 });
    var ms = Date.now() - t0;
    var j = null;
    try { j = JSON.parse(String((r && (r.body || r.content)) || "{}")); } catch (e) { j = null; }
    if (r && r.status === 200 && j && j.code === 200) return { host: h, ok: true, ms: ms };
    var why = "";
    if (r && r.status === 403) why = "403 被拦";
    else if (r && r.status === 429) why = "429 限流";
    else if (r && r.status) why = "HTTP " + r.status;
    else if (!j) why = "非 JSON";
    else why = "code " + (j.code || "?");
    return { host: h, ok: false, ms: ms, why: why };
  } catch (e) {
    return { host: h, ok: false, ms: Date.now() - t0, why: String(e.message || e).slice(0, 20) };
  }
}

// 串行精确测全部线路。10 条 × ~100ms ≈ 1 秒，值得。
function hostProbeAll() {
  var out = [];
  for (var i = 0; i < HOSTS.length; i++) out.push(hostProbeExact(HOSTS[i], 6000));
  return out;
}

// 延迟分级（实测 63–134ms；300ms 以上算慢）
function hostGrade(ms) {
  if (ms <= 100) return "🟢 快";
  if (ms <= 300) return "🟡 中";
  return "🔴 慢";
}

// 📶 延迟排序 + 一键切最快（带延迟显示）
function actPing(ctx) {
  if (typeof ui !== "undefined" && ui && ui.toast) ui.toast("正在精确测 " + HOSTS.length + " 条线路…");
  var t0 = Date.now();
  var res = hostProbeAll();
  var cost = Math.max(1, Date.now() - t0);
  var ok = [], i;
  for (i = 0; i < res.length; i++) if (res[i].ok) ok.push(res[i]);
  ok.sort(function (a, b) { return a.ms - b.ms; });
  if (ok.length) latSave(ok.map(function (x) { return x.host; }), null);

  var cur = host();
  var lines = [];
  for (i = 0; i < res.length; i++) {
    var x = res[i];
    var name = x.host.replace("https://", "");
    var mark = x.host === cur ? "▶ " : "  ";
    if (x.ok) {
      var ratio = ok.length ? x.ms / ok[0].ms : 1;
      lines.push(mark + name + "  " + x.ms + "ms  " + hostGrade(x.ms) +
        (ratio > 1.05 ? "  " + ratio.toFixed(1) + "x" : ""));
    } else {
      lines.push(mark + name + "  ⛔ " + (x.why || ""));
    }
  }
  var head;
  if (ok.length) {
    head = "📶 延迟排序｜可用 " + ok.length + "/" + res.length + "｜国内直连｜测速耗时 " + cost + "ms\n最快 " +
      ok[0].host.replace("https://", "") + " " + ok[0].ms + "ms " + hostGrade(ok[0].ms) +
      "｜当前 " + cur.replace("https://", "") + "\n";
  } else {
    head = "❌ " + res.length + " 条线路全不通（测速耗时 " + cost + "ms）\n";
  }
  return head + lines.join("\n");
}

// 🚀 测速并自动切到最快
function actBest(ctx) {
  if (typeof ui !== "undefined" && ui && ui.toast) ui.toast("正在测速 " + HOSTS.length + " 条线路…");
  var t0 = Date.now();
  var res = hostProbeAll();
  var cost = Math.max(1, Date.now() - t0);
  var ok = [], i;
  for (i = 0; i < res.length; i++) if (res[i].ok) ok.push(res[i]);
  ok.sort(function (a, b) { return a.ms - b.ms; });
  if (!ok.length) {
    var why0 = [];
    for (i = 0; i < res.length && i < 4; i++) {
      why0.push(res[i].host.replace("https://", "") + " " + (res[i].why || "不通"));
    }
    return "❌ " + HOSTS.length + " 条线路全不通（" + cost + "ms）\n" + why0.join("\n") +
      "\n换网络或稍后重试。";
  }
  latSave(ok.map(function (x) { return x.host; }), null);
  var cur = host();
  var curMs = 0, curOk = false;
  for (i = 0; i < res.length; i++) if (res[i].host === cur) { curMs = res[i].ms; curOk = res[i].ok; }
  vars.set("host", ok[0].host);

  var note;
  if (cur === ok[0].host) note = "当前已是最快线路";
  else if (!curOk) note = "原线路不通，已切到 " + ok[0].host.replace("https://", "");
  else note = "已切到 " + ok[0].host.replace("https://", "") + "（" + curMs + "ms → " + ok[0].ms +
    "ms，快 " + ((1 - ok[0].ms / Math.max(1, curMs)) * 100).toFixed(0) + "%）";

  var tail = [];
  for (i = 0; i < ok.length && i < 3; i++) tail.push(ok[i].host.replace("https://", "") + " " + ok[i].ms + "ms");
  return "🚀 " + note + "\n可用 " + ok.length + "/" + res.length + "｜测速耗时 " + cost + "ms" +
    "\n前三：" + tail.join(" / ");
}

