fn htmlList(html) {
  let raw = match(html, 'exemptComic-box[^>]*list="([^"]+)"', 1)
  if str(raw) == '' {
    return []
  }
  // 站点 list 属性是 Python 风格 {'key': 'val'}，值内含单引号时用 &quot; 定界
  // 按上下文模式替换，避免把值内引号（如 Don't）误伤
  let s = replaceText(raw, '{&#x27;', '{"')
  s = replaceText(s, ', &#x27;', ', "')
  s = replaceText(s, '&#x27;:', '":')
  s = replaceText(s, ': &#x27;', ': "')
  s = replaceText(s, '&#x27;,', '",')
  s = replaceText(s, '&#x27;}', '"}')
  s = replaceText(s, '&quot;', '"')
  s = replaceText(s, '&#x27;', "'")
  s = replaceText(s, '&#39;', "'")
  s = htmlDecode(s)
  return json(s)
}

fn tocChapters(p) {
  if p == null {
    return []
  }
  if p.groups == null {
    return []
  }
  let out = []
  for g in values(p.groups) {
    for c in g.chapters {
      if c.id != null {
        push(out, c)
      }
    }
  }
  let asc = 0
  let desc = 0
  for c, i in out {
    if i > 0 {
      let a = int(match(out[i - 1].name, '(\d+)', 1), -1)
      let b = int(match(c.name, '(\d+)', 1), -1)
      if a >= 0 && b >= 0 {
        if a < b {
          asc = asc + 1
        }
        if a > b {
          desc = desc + 1
        }
      }
    }
  }
  if desc > asc {
    let rev = []
    for c, i in out {
      push(rev, out[len(out) - 1 - i])
    }
    return rev
  }
  return out
}

fn imagesOf(v) {
  if v == null {
    return []
  }
  let out = []
  for x in v {
    let u = ''
    if typeOf(x) == 'string' {
      u = x
    } else if x != null {
      u = default(x.url, x.src, '')
    }
    if startsWith(u, 'http') {
      push(out, u)
    }
  }
  return out
}

