// ===== 禁漫天堂（jmtt1 / 18mh 新版 jm-* 前端）轻页原生 v1 =====
// 结构：工具 -> 线路 -> 请求 -> 列表解析 -> 五阶段 -> 图片解密 -> 分支自检 -> 视频链
// 约束：QuickJS（无 DOM / cheerio / Node），只做字符串与正则；请求走 http.*
// 三模式不靠开关：URL 段 /comic/ /novel/ /mv/ 决定类型，每本书各自声明 type

// ---------- 工具 ----------
var ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", ldquo: '\u201c', rdquo: '\u201d', lsquo: '\u2018', rsquo: '\u2019', hellip: '\u2026', mdash: '\u2014', ndash: '\u2013', middot: '\u00b7', nbsp: ' ', ensp: ' ' };
function unesc(s) {
  return String(s == null ? '' : s).replace(/&#x([0-9a-fA-F]+);|&#(\d+);|&([a-zA-Z]+);/g, function (all, h, d, n) {
    if (h) return String.fromCharCode(parseInt(h, 16));
    if (d) return String.fromCharCode(parseInt(d, 10));
    return ENT[n] != null ? ENT[n] : all;
  });
}
function clean(s) {
  return unesc(String(s == null ? '' : s).replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
}
function pick(s, re, i) {
  var m = String(s == null ? '' : s).match(re);
  return m ? clean(m[typeof i === 'number' ? i : 1]) : '';
}
function nOf(v) {
  var n = parseInt(v, 10);
  return (n > 0 ? n : 1);
}
// 段类型：只有三类
function segOf(url) {
  var u = String(url || '');
  if (/\/novel(\/|_)/.test(u)) return 'novel';
  if (/\/mv(\/|$|\?)/.test(u)) return 'mv';
  return 'comic';
}
function segType(seg) {
  if (seg === 'novel') return 'text';
  if (seg === 'mv') return 'video';
  return 'comic';
}

// ---------- 线路 ----------
// *.bomei.cc 任意单词子域同源（站点发布页词表随机取词）。
// 2026-11-01 时旧后缀 yyc2mhau.cc 可用，2026-11-10 已全部失效，故换成 bomei.cc
var HOSTS = [
  'https://abandon.bomei.cc',
  'https://ability.bomei.cc',
  'https://able.bomei.cc',
  'https://above.bomei.cc',
  'https://abroad.bomei.cc',
  'https://absence.bomei.cc'
