// ---------- 请求 ----------
var RETRYABLE = /2300999|2300016|2300056|http\/?2|framing layer|timeout|reset/i;
function jmGet(path, desc) {
  var url = jmAbs(path);
  var r = null, why = '';
  for (var i = 0; i < 2; i++) {
    try { r = http.get(url, { headers: hdr() }); } catch (e) { r = { ok: false, status: 0, body: '', error: String((e && e.message) || e) }; }
    if (r && r.ok && r.status === 200 && String(r.body || '').length > 0) break;
    why = String((r && r.error) || '');
    if (i === 0 && (r && r.status === 200 || RETRYABLE.test(why))) { try { sleep(250); } catch (e2) {} continue; }
    break;
  }
  var code = r && r.status;
  if (!r || !r.ok || code !== 200) {
    throw new Error((desc || '请求') + '失败：' + (code ? 'HTTP ' + code : '网络错误') + (why ? '（' + why + '）' : '') + '\n线路 ' + hostOf());
  }
  var text = String(r.body || '');
  if (!text.length) throw new Error((desc || '请求') + '返回空内容\n线路 ' + hostOf());
  if (/Just a moment|Attention Required|cf-browser-verification/i.test(text.slice(0, 3000))) {
    throw new Error((desc || '请求') + '被人机验证拦截\n换线路再试');
