    // 分类/标签（作者链接单独取出）
    var kind = '', author = '';
    var cm = segHtml.match(/class="jm-(?:card|vcard)__cat"[^>]*>([\s\S]*?)<\/div>/);
    if (cm) {
      var parts = [], cre = /<a\b[^>]*>([\s\S]{0,30}?)<\/a>/g, cmm;
      while ((cmm = cre.exec(cm[1])) !== null) {
        var t = clean(cmm[1]);
        if (!t) continue;
        if (/\/all\/author\//.test(cmm[0])) { if (!author) author = t; continue; }
        parts.push(t);
      }
      if (!author) { var am0 = segHtml.match(/<a[^>]*href="[^"]*\/all\/author\/[^"]*"[^>]*>([\s\S]{0,40}?)<\/a>/); if (am0) author = clean(am0[1]); }
      kind = parts.join(' \u00b7 ');
    }
    var st = segHtml.match(/class="jm-(?:card|vcard)__badge[^"]*"[^>]*>([\s\S]{0,20}?)<\/span>/);
    if (st) { var s2 = clean(st[1]); if (s2) kind = kind ? kind + ' \u00b7 ' + s2 : s2; }
    var dur = segHtml.match(/class="jm-vcard__dur"[^>]*>([\s\S]{0,20}?)<\/span>/);
    if (dur) { var d2 = clean(dur[1]); if (d2) kind = kind ? kind + ' \u00b7 ' + d2 : d2; }
    var item = {
      name: name,
      bookUrl: host + url,
      coverUrl: cover,
      kind: kind,
      type: segType(segOf(url))
    };
    if (author) item.author = author;
    else if (segOf(url) === 'mv') item.author = '禁漫天堂';
    out.push(item);
  }
  return out;
}

// 行卡 a.jm-rrow（最近更新）
function pRows(html, seg, host) {
  var h = String(html || '');
  var out = [], seen = {}, re = /<a class="jm-rrow[^"]*"[^>]*>([\s\S]*?)<\/a>/g, m;
  while ((m = re.exec(h)) !== null) {
    var tag = m[0].slice(0, 300), segHtml = m[1];
    var lm = tag.match(/href="(\/comic\/detail\/\d+|\/novel\/detail\/\d+|\/mv\/detail\/\d+)"/);
    if (!lm) continue;
    var url = lm[1], key = url.split('/').pop();
    if (seen[key]) continue;
    seen[key] = 1;
    var name = '';
    var nm = segHtml.match(/class="jm-rrow__title"[^>]*>([\s\S]*?)<\/span>/);
    if (nm) name = clean(nm[1]);
    if (!name) { var im = segHtml.match(/alt="([^"]{1,200})"/); if (im) name = clean(im[1]); }
    if (!name) continue;
    var cover = firstSrc(segHtml);
    if (cover && !isCover(cover)) cover = '';
    var kind = '', last = '', author = '';
    var am2 = segHtml.match(/<a[^>]*href="[^"]*\/all\/author\/[^"]*"[^>]*>([\s\S]{0,40}?)<\/a>/);
    if (am2) author = clean(am2[1]);
    var km = segHtml.match(/class="jm-rrow__c"[^>]*>([\s\S]{0,30}?)<\/span>/);
    if (km) kind = clean(km[1].replace(/<a[^>]*href="[^"]*\/all\/author\/[^"]*"[^>]*>[\s\S]{0,40}?<\/a>/g, ' '));
    var lm2 = segHtml.match(/class="jm-rrow__m"[^>]*>([\s\S]{0,40}?)<\/span>/);
    if (lm2) last = clean(lm2[1]);
    var item2 = {
      name: name, bookUrl: host + url, coverUrl: cover, kind: kind,
      lastChapter: last, type: segType(segOf(url))
    };
    if (author) item2.author = author;
    else if (segOf(url) === 'mv') item2.author = '禁漫天堂';
    out.push(item2);
  }
  return out;
}

// 榜单：前 3 名 a.jm-rp-stand（领奖台），4-30 名 a.jm-rkrow
function pRank(html, seg, host) {
  var h = String(html || '');
  var out = [], seen = {}, re = /<a class="jm-(rp-stand|rkrow)[^"]*"([^>]*)>([\s\S]*?)<\/a>/g, m;
  while ((m = re.exec(h)) !== null) {
    var kind2 = m[1], attrs = m[2], segHtml = m[3];
    var lm = attrs.match(/href="(\/[a-z]+\/detail\/\d+)"/) || segHtml.match(/href="(\/[a-z]+\/detail\/\d+)"/);
    if (!lm) continue;
    var url = lm[1], key = url.split('/').pop();
    if (seen[key]) continue;
    seen[key] = 1;
    var name = '';
    if (kind2 === 'rp-stand') {
      var a1 = segHtml.match(/class="jm-rp-stitle"[^>]*>([\s\S]*?)<\/div>/);
      if (a1) name = clean(a1[1]);
    } else {
      var a2 = segHtml.match(/class="jm-rkrow__title"[^>]*>([\s\S]*?)<\/span>/);
      if (a2) name = clean(a2[1]);
    }
    if (!name) { var im = segHtml.match(/alt="([^"]{1,200})"/); if (im) name = clean(im[1]); }
    if (!name) continue;
    var cover = firstSrc(segHtml);
    if (cover && !isCover(cover)) cover = '';
    var k1 = segHtml.match(/class="jm-rp-ssub"[^>]*>([\s\S]{0,60}?)<\/div>/);
    var k2 = segHtml.match(/class="jm-rkrow__sub"[^>]*>([\s\S]{0,80}?)<\/div>/);
    var kind = k1 ? clean(k1[1]) : (k2 ? clean(k2[1]) : '');
    var author = '';
    var am3 = segHtml.match(/<a[^>]*href="[^"]*\/all\/author\/[^"]*"[^>]*>([\s\S]{0,40}?)<\/a>/);
    if (am3) author = clean(am3[1]);
    var item3 = { name: name, bookUrl: host + url, coverUrl: cover, kind: kind, type: segType(segOf(url)) };
    if (author) item3.author = author;
    else if (segOf(url) === 'mv') item3.author = '禁漫天堂';
    out.push(item3);
  }
  return out;
}

function pList(html, seg, host) {
  var h = String(html || '');
  if (h.indexOf('jm-card') >= 0 || h.indexOf('jm-vcard') >= 0) {
    var c = pCards(h, seg, host);
    if (c.length) return c;
  }
  if (h.indexOf('jm-rrow') >= 0) {
    var r = pRows(h, seg, host);
    if (r.length) return r;
  }
  return pRank(h, seg, host);
}

// ---------- 列表作者补齐 ----------
// 漫画列表卡不带作者（实测 4 个列表页 author 链接数均为 0），只能逐本回详情取；
// 限流 10/10s，所以只补前 12 本，其余留空，打开详情时宿主会再补
function detailAuthor(id, seg) {
  try {
    var h = jmGet('/' + seg + '/detail/' + id, '补作者');
    var m = h.match(/<a[^>]*href="[^"]*\/all\/author\/[^"]*"[^>]*>([\s\S]{0,40}?)<\/a>/);
    if (m) return clean(m[1]);
    var ld = h.match(/"author":\s*\{[^}]*"name":\s*"([^"]{1,60})"/);
    if (ld) return clean(ld[1]);
  } catch (e) {}
  return '';
}
function fillAuthors(rows, seg) {
  var filled = 0;
  for (var i = 0; i < rows.length && filled < 12; i++) {
    if (rows[i].author) continue;
    if (rows[i].type !== 'comic') continue;
    var id = (String(rows[i].bookUrl || '').match(/\/detail\/(\d+)/) || [])[1];
    if (!id) continue;
    var a = detailAuthor(id, 'comic');
    if (a) { rows[i].author = a; filled++; }
  }
  return rows;
}

// ---------- 搜索 ----------
// 站内按整词命中；三类各自一套列表页，接口用 ?key_word=&page= （实测 200 且可翻页）
function stageSearch(ctx) {
  var kw = String((ctx && ctx.key) || '').replace(/^\s+|\s+$/g, '');
  if (!kw) throw new Error('搜索词为空');
  var pg = nOf(ctx && ctx.page);
  var host = hostOf();
  var enc = encodeURIComponent(kw);
  var segs = ['comic', 'novel', 'mv'];
  var out = [];
  for (var i = 0; i < segs.length; i++) {
    var seg = segs[i];
    var body = null;
    try {
      body = jmGet('/' + seg + '/all?key_word=' + enc + '&page=' + pg, '搜索');
    } catch (e) {
      if (i === 0) throw e;
      continue;
    }
    var rows = pList(body, seg, host);
    for (var j = 0; j < rows.length; j++) out.push(rows[j]);
  }
  if (!out.length && pg === 1) {
    try {
      if (typeof ui !== 'undefined' && ui && typeof ui.toast === 'function') {
        ui.toast('没搜到「' + kw + '」：站内按整词命中，换个更短/更长的词试试');
      }
    } catch (e) {}
  }
  return out;
}

// ---------- 发现 ----------
// 榜单 tab -> [sort, period]
function rankKV(tab) {
  var map = {
    day: ['popular', 'day'], week: ['popular', 'week'], month: ['popular', 'month'], year: ['popular', 'year'],
    collect: ['favorite', 'year'], favorite: ['favorite', 'year'],
    hot: ['favorite', 'year'], new: ['new', 'day'], finished: ['finished', 'day']
  };
  return map[String(tab || '').toLowerCase()] || map.day;
}

function rankBoard(seg, tab) {
  var host = hostOf();
  var kv = rankKV(tab);
  var theme = (seg === 'novel' ? 'novel' : 'comic');
  var q = '/rank/board?theme=' + theme + '&sort=' + kv[0] + '&period=' + kv[1];
  var r = null;
  try { r = http.get(host + q, { headers: hdr() }); } catch (e) { r = null; }
  if (r && r.ok && r.status === 200) {
    var j = null;
    try { j = JSON.parse(String(r.body || '')); } catch (e) { j = null; }
    var inner = j && j.data && j.data.html;
    if (inner) {
      var rows = pRank(inner, seg, host);
      if (rows.length) return rows;
    }
  }
  return null;
}

function stageExplore(ctx) {
  var host = hostOf();
  var pg = nOf(ctx && ctx.page);
  // 原生会把菜单地址里的 {{page}} 先展开；这里同时兜住"没展开"的情况
  var u = String((ctx && (ctx.url || (ctx.menu && ctx.menu.url))) || '/comic/all');
  u = u.replace('{{page}}', String(pg));
  var base = u.split('#')[0].replace(/\/+$/, '');
  var tab = (u.match(/#tab=([a-z]+)/) || [])[1] || 'day';
  var seg = segOf(base);
  if (!base) base = '/' + seg + '/all';

  // 榜单：/comic/rank、/novel/rank（单页，没有 {{page}}）
  if (/^\/(comic|novel)\/rank/.test(base)) {
    var rb = rankBoard(seg, tab);
    if (rb && rb.length) return rb;
    if (pg > 1) return [];
    return pRank(jmGet('/' + seg + '/rank', '排行榜'), seg, host);
  }

  // 单页列表：最近更新（/comic/newest、/novel/newest、/mv/new）都是"按天"前端分页，
  // 服务端各页返回同一份内容，所以只取第 1 页
  if (/\/(newest|new)$/.test(base)) {
    if (pg > 1) return [];
    return fillAuthors(pList(jmGet(base, '分类'), seg, host), seg);
  }

  // 其余分类地址已含页码（/x/all/page/N、/x/all/code/N、/x/tag/enc/N），直接取
  return fillAuthors(pList(jmGet(u, '分类'), seg, host), seg);
}

// ---------- 详情 ----------
function stageDetail(ctx) {
  var bookUrl = String((ctx && ctx.book && (ctx.book.bookUrl || ctx.book.tocUrl)) || '');
  var host = hostOf();
  var seg = segOf(bookUrl);

  // 视频：详情结构是 jm-vd-*，标题/简介/封面另走一套
  if (seg === 'mv') {
    var mid = (bookUrl.match(/\/mv\/detail\/(\d+)/) || [])[1];
    if (!mid) throw new Error('视频详情拿不到 id：' + bookUrl);
    var mvHtml = jmGet('/mv/detail/' + mid, '详情');
    var mvName = pick(mvHtml, /class="jm-vd-title"[^>]*>([\s\S]{0,300}?)<\/div>/)
      || pick(mvHtml, /class="jm-crumb__title"[^>]*>([\s\S]{0,300}?)<\/h1>/)
      || pick(mvHtml, /og:title"\s+content="([^"]{1,200})"/).split('|')[0];
    if (!mvName) throw new Error('视频详情解析不到标题，站点结构可能已改版');
    var mvIntro = pick(mvHtml, /class="jm-vd-desc__text"[^>]*>([\s\S]{0,4000}?)<\/p>/);
    // 封面：og:image 是 social-cover（已明文），还原 base64 拿到原图路径再走 coverDecode
    var mvCover = '';
    var og = mvHtml.match(/property="og:image"\s+content="([^"]+)"/);
    if (og) {
      var bm = og[1].match(/social-cover\/([A-Za-z0-9+/=]+)\.\w+$/);
      if (bm) {
        var rawPath = '';
        try { rawPath = unbase64(bm[1]); } catch (e) { rawPath = ''; }
        if (rawPath && rawPath.charAt(0) === '/') mvCover = 'https://xi.dzuxta.cn' + rawPath;
      }
    }
    if (!mvCover) {
      var mcv = mvHtml.match(/data-src="(https:\/\/xi\.dzuxta\.cn\/[^"]+)"/);
      if (mcv) mvCover = unesc(mcv[1]);
    }
    // 分类 / 时长 / 标签（JSON-LD）
    var mvKind = '';
    var g = mvHtml.match(/"genre":\s*\[([^\]]*)\]/);
    if (g) {
      var parts = [], gre = /"([^"]+)"/g, gm;
      while ((gm = gre.exec(g[1])) !== null) if (gm[1]) parts.push(gm[1]);
      mvKind = parts.join(' \u00b7 ');
    }
    var mvDur = (mvHtml.match(/"duration":\s*"PT(\d+)M(\d+)S"/) || []);
    if (mvDur.length) {
      var dtxt = mvDur[1] + ':' + (mvDur[2].length < 2 ? '0' + mvDur[2] : mvDur[2]);
      mvKind = mvKind ? mvKind + ' \u00b7 ' + dtxt : dtxt;
    }
    var mvUp = (mvHtml.match(/"uploadDate":\s*"([^"]+)"/) || [])[1] || '';
    return {
      name: mvName,
      author: '禁漫天堂',
      bookUrl: host + '/mv/detail/' + mid,
      coverUrl: mvCover,
      intro: mvIntro || mvName,
      kind: mvKind,
      status: '已完结',
      updateTime: mvUp.replace('T', ' ').slice(0, 16),
      lastChapter: dtxt ? '时长 ' + dtxt : '',
      type: 'video'
    };
  }

  // 漫画 / 小说：同一套 jm-dt-*
  var cid = (bookUrl.match(/\/(?:comic|novel)\/detail\/(\d+)/) || [])[1];
  if (!cid) throw new Error('详情阶段拿不到作品 id：' + bookUrl);
  var html = jmGet('/' + seg + '/detail/' + cid, '详情');

  var name = pick(html, /<h1 class="jm-dt-title"[^>]*>([\s\S]{0,300}?)<\/h1>/)
    || pick(html, /property="og:title"\s+content="([^"]{1,200})"/).split('|')[0];
  if (!name) throw new Error('详情页解析不到标题，站点结构可能已改版');

  // 元信息：两行 div.jm-dt-meta —— 第一行 分类/作者/状态/更新时间，第二行 最新章节
  var metas = [], mre = /<div class="jm-dt-meta"[^>]*>([\s\S]*?)<\/div>/g, mm;
  while ((mm = mre.exec(html)) !== null) metas.push(mm[1]);

  var cats = [], author = '', status = '', upd = '', lastCh = '';
  for (var i = 0; i < metas.length; i++) {
    var mseg = metas[i];
    var spans = [], sre = /<span[^>]*>([\s\S]*?)<\/span>/g, sm;
    while ((sm = sre.exec(mseg)) !== null) spans.push(sm[1]);
    for (var s = 0; s < spans.length; s++) {
      var rawSpan = spans[s], txt = clean(rawSpan.replace(/<svg[\s\S]*?<\/svg>/g, ' '));
      if (!txt) continue;
      if (/\/all\/author\//.test(rawSpan)) { if (!author) author = txt; continue; }
      if (/\/all\/(?:[a-z0-9]{2}|[a-z0-9]{2,}[^"]*)"[^>]*>/.test(rawSpan) && /\/(?:comic|novel)\/all\/[a-z0-9]{2}/.test(rawSpan)) { cats.push(txt); continue; }
      if (/\/(?:comic|novel)\/chapter\/|\/novel_chapter\//.test(rawSpan)) { if (!lastCh) lastCh = txt; continue; }
      if (/^\d{4}-\d{2}-\d{2}/.test(txt)) { upd = txt.replace(/\s*更新\s*$/, ''); continue; }
      if (/^(连载中|已完结|已下架|休刊|完结|连载)$/.test(txt)) { if (!status) status = txt; continue; }
    }
  }

  var st = html.match(/class="jm-dt-pill[^"]*jm-dt-pill--st"[^>]*>([\s\S]{0,20}?)<\/span>/);
  if (st) { var s3 = clean(st[1]); if (s3) status = s3; }

  // 封面：加密整文件，交给顶层 coverDecode
  var cover = '';
  var cm2 = html.match(/<img class="jm-dt-cover__img"[^>]*data-src="([^"]+)"/);
  if (!cm2) cm2 = html.match(/<img[^>]*class="jm-dt-cover__img"[^>]*src="([^"]+)"/);
  if (cm2) cover = unesc(cm2[1]);
  if (cover && !isCover(cover)) cover = '';

  var intro = pick(html, /<p class="jm-dt-desc__p"[^>]*>([\s\S]{0,4000}?)<\/p>/);

  var tags = [], tre = /<a class="jm-dt-chip"[^>]*>([\s\S]{0,200}?)<\/a>/g, tm2;
  while ((tm2 = tre.exec(html)) !== null) {
    var tg = clean(tm2[1]);
    if (tg && tags.indexOf(tg) < 0) tags.push(tg);
  }

  var kind = cats.concat(tags).join(' \u00b7 ');
  return {
    name: name,
    author: author || '未知',
    bookUrl: host + '/' + seg + '/detail/' + cid,
    coverUrl: cover,
    intro: intro || name,
    kind: kind,
    status: status || (lastCh ? '连载中' : '已完结'),
    updateTime: upd,
    lastChapter: lastCh,
    type: segType(seg)
  };
}

// ---------- 目录 ----------
// 漫画：a.jm-dt-ch -> /comic/chapter/{id}/{no}
// 小说：a.jm-dt-ch -> /novel_chapter/{id}/{no}.html
// 视频：单集，章节地址指回详情页，正文阶段解析播放链
function stageToc(ctx) {
  var bookUrl = String((ctx && ctx.book && (ctx.book.bookUrl || ctx.book.tocUrl)) || '');
  var host = hostOf();
  var seg = segOf(bookUrl);

  if (seg === 'mv') {
    var mid = (bookUrl.match(/\/mv\/detail\/(\d+)/) || [])[1];
    if (!mid) throw new Error('目录阶段拿不到视频 id：' + bookUrl);
    return [{ title: '\u25b6 开始观看', url: host + '/mv/detail/' + mid }];
  }

  var cid = (bookUrl.match(/\/(?:comic|novel)\/detail\/(\d+)/) || [])[1];
  if (!cid) throw new Error('目录阶段拿不到作品 id：' + bookUrl);
  var html = jmGet('/' + seg + '/detail/' + cid, '目录');

  // 漫画 /comic/chapter/{id}/{no}、小说 /novel_chapter/{id}/{no}.html；DOM 即正序
  var isComic = seg === 'comic';
  var re = isComic
    ? /<a class="jm-dt-ch[^"]*" href="(\/comic\/chapter\/\d+\/(\d+))"[^>]*>([\s\S]*?)<\/a>/g
    : /<a class="jm-dt-ch[^"]*" href="(\/novel_chapter\/\d+\/(\d+)\.html)"[^>]*>([\s\S]*?)<\/a>/g;
  var unit = isComic ? '话' : '章';
  var out = [], seen = {}, m;
  while ((m = re.exec(html)) !== null) {
    var href = m[1];
    if (seen[href]) continue;
    seen[href] = 1;
    var body = m[3];
    var no = pick(body, /class="jm-dt-ch__no"[^>]*>([\s\S]{0,40}?)<\/span>/);
    var title = pick(body, /class="jm-dt-ch__t"[^>]*>([\s\S]{0,300}?)<\/span>/);
    if (!title) title = no || ('第' + m[2] + unit);
    else if (no) {
      var fn = no.replace(/\s+/g, ''), ft = title.replace(/\s+/g, '');
      if (ft !== fn && ft.indexOf(fn) < 0) title = no + ' ' + title;
    }
    var date = pick(body.replace(/<svg[\s\S]*?<\/svg>/g, ' '), /class="jm-dt-ch__d"[^>]*>([\s\S]{0,300}?)<\/span>/);
    out.push({ title: title, url: host + href, tag: date });
  }
  if (!out.length) throw new Error('目录为空：站点结构可能已改版（找不到 a.jm-dt-ch）');
  return out;
}

// ---------- 正文 ----------
// 漫画图：只取 section.jm-rd-pages 内的图（页面其它 img 是广告/UI）
function stageContent(ctx) {
  var bk = ctx && ctx.book, ch = ctx && ctx.chapter;
  var raw = String((ch && (ch.url || ch.chapterUrl)) || (bk && (bk.chapterUrl || bk.bookUrl)) || '');
  var seg = segOf(raw);

  if (seg === 'mv') {
    var mid = (raw.match(/\/mv\/(?:detail\/|embed\?id=)(\d+)/) || [])[1];
    if (!mid) throw new Error('视频正文拿不到 id：' + raw);
    return videoContent(mid);
  }

  if (seg === 'novel') {
    var html = jmGet(raw, '正文');
    var box = html;
    var bi = html.indexOf('data-rd-text');
    if (bi >= 0) {
      var st = html.indexOf('>', bi);
      var en = html.indexOf('data-rd-text-end', st);
      if (en < 0) en = html.indexOf('</article>', st);
      if (en < 0) en = Math.min(html.length, st + 200000);
      box = html.slice(st + 1, en);
    }
    var ps = box.match(/<p>[\s\S]*?<\/p>/g) || [];
    var lines = [];
    for (var i = 0; i < ps.length; i++) {
      var x = ps[i].replace(/^<p>/, '').replace(/<\/p>$/, '').replace(/<[^>]+>/g, '');
      x = clean(x);
      if (x) lines.push(x);
    }
    if (!lines.length) throw new Error('正文为空：找不到 .jm-rd-text 段落');
    return { text: lines.join('\n') };
  }

  // 漫画
  var chHtml = jmGet(raw, '正文');
  var imgs = extractImages(chHtml);
  if (!imgs.length) throw new Error('本章没有解析到图片');
  return { images: imgs };
}

function extractImages(html) {
  var h = String(html || '');
  var box = h;
  var si = h.indexOf('<section class="jm-rd-pages"');
  if (si < 0) si = h.indexOf('class="jm-rd-pages"');
  if (si >= 0) {
    var se = h.indexOf('</section>', si);
