// 图片解密：站内图整体 AES-128-CBC 加密；少数已是明文（广告位/旧 CDN），先验魔数
function isImageBytes(b) {
  if (!b || b.length < 4) return false;
  var b0 = b[0], b1 = b[1], b2 = b[2], b3 = b[3];
  if (b0 === 0xFF && b1 === 0xD8) return true;
  if (b0 === 0x89 && b1 === 0x50 && b2 === 0x4E && b3 === 0x47) return true;
  if (b0 === 0x47 && b1 === 0x49 && b2 === 0x46) return true;
  if (b0 === 0x52 && b1 === 0x49 && b2 === 0x46 && b3 === 0x46) return true;
  return false;
}
var IMG_KEY = '66356439363564663735333336323730';
var IMG_IV = '39376236303339346162633266626531';
function decodeImage(bytes, ctx) {
  if (!bytes || !bytes.length) return bytes;
  if (isImageBytes(bytes)) return bytes;
  var out = null;
  try { out = image.decrypt('AES/CBC/PKCS7Padding', bytes, IMG_KEY, IMG_IV); } catch (e) { out = null; }
  if (out && isImageBytes(out)) return out;
  var n = bytes.length - (bytes.length % 16);
  if (!n) return bytes;
  var raw = null;
  try { raw = image.decrypt('AES/CBC/NoPadding', bytes.subarray(0, n), IMG_KEY, IMG_IV); } catch (e) { raw = null; }
  if (!raw) return bytes;
  // JPEG 尾巴切 FFD9
