  for (var k = raw.length - 2; k >= 0 && k > raw.length - 128; k--) {
    if (raw[k] === 0xFF && raw[k + 1] === 0xD9) { end = k + 2; break; }
  }
  if (end > 0) return raw.subarray(0, end);
  return raw;
}

// ---------- 视频链 ----------
// /mv/detail/{id} -> /mv/embed?id={id}（packer 混淆）-> /videos/detail_embed.js?img=&u=&t=（再一层 packer）-> /media/m3u8?...
// 静态解两层 packer 即可拿到播放地址，交给原生播放器；videoPage 留原站网页做回退
function unpackPacker(src) {
  var s = String(src || '');
  var m = s.match(/eval\(function\(p,a,c,k,e,d\)\{[\s\S]*?\}\('([\s\S]*?)',(\d+),(\d+),'([\s\S]*?)'\.split\('\|'\)/);
  if (!m) return '';
  var payload = m[1], a = parseInt(m[2], 10), c = parseInt(m[3], 10);
  var k = m[4].split('|');
  function enc(x) { return (x < a ? '' : enc(parseInt(x / a, 10))) + ((x = x % a) > 35 ? String.fromCharCode(x + 29) : x.toString(36)); }
  var out = payload;
  for (var i = c - 1; i >= 0; i--) {
    if (!k[i]) continue;
    out = out.replace(new RegExp('\\b' + enc(i) + '\\b', 'g'), k[i]);
  }
  return out;
}

