fn syOpus(u) {
  let s = trim(str(u ?? ''))
  if (s == '' || s == 'null') {
    return ''
  }
  let fixed = match(s, '.*(https?://[^/]+/.*)$', 1)
  if (fixed != '') {
    s = fixed
  }
  if (startsWith(s, '//')) {
    s = 'https:' + s
  }
  if (startsWith(s, 'http://')) {
    s = 'https://' + substring(s, 7)
  }
  return replace(s, '/star/albumcover/240/', '/star/albumcover/500/')
}

