fn syTier(v) {
  if (v >= 8000) {
    return 2.2
  }
  if (v >= 3000) {
    return 2.0
  }
  if (v >= 1500) {
    return 1.7
  }
  if (v >= 700) {
    return 1.4
  }
  if (v >= 300) {
    return 1.0
  }
  if (v >= 100) {
    return 0.6
  }
  return 0.2
}

fn syRate(b) {
