  }
  let ft = str(b.filetype ?? '')
  let bonus = ft == '完结' ? 0.7 : (contains(ft, '连载') ? 0.3 : 0)
  let s = str(round(6.3 + syTier(v) + bonus, 1))
  return contains(s, '.') ? s + '分' : s + '.0分'
}

