    return ''
  }
  if (len(names) <= 2) {
    return join(names, ', ')
  }
  return str(names[0]) + ', ' + str(names[1]) + ' 等 ' + str(len(names)) + ' 人'
}

// 听友 tingyou.fm · 原生
// 详情地址用标记地址 https://www.tingyou.fm/album/<id>，取回专辑 id
fn tyAid(u) {
  return str(match(str(u), '/album/([0-9]+)', 1))
}
// 章节地址用标记地址 https://www.tingyou.fm/c/<index>，取回站点要的 chapter_idx（从 1 开始）
fn tyIdx(u) {
  return str(match(str(u), '/c/([0-9]+)', 1))
}

// 博看有声 · 原生
// 从详情地址 https://api.bookan.com.cn/voice/album/units?album_id=<id>&... 取回专辑 id
fn bkAid(u) {
  return str(match(str(u), 'album_id=([0-9]+)', 1))
}
// 目录分页：current_page < last_page 时把地址里的 page 加一
fn bkNext(bu, cur, last) {
  let c = int(str(cur), 1)
  let t = int(str(last), 1)
  if (c >= t) { return '' }
  return replace(str(bu), 'page=[0-9]+', 'page=' + str(c + 1))
}

// 云图有声 · 原生
// 从详情地址 …/getChapters/<token>/<bookId>/true/asc?… 取回 bookId
fn ytAid(u) {
