}
// 目录分页：pageNumber < totalPage 时把地址里的 pageNum 加一
fn ytNext(bu, cur, total) {
  let c = int(str(cur), 1)
  let t = int(str(total), 1)
  if (t < 1) { t = 1 }
  if (c >= t) { return '' }
  return replace(str(bu), 'pageNum=[0-9]+', 'pageNum=' + str(c + 1))
}

fn cleanFullTitle(t) {
  let s = trim(default(t, ''))
  let head = trim(replace(s, '^(?:【[^【】]*】)+', '', 'g'))
  if len(head) >= 2 { s = head }
  return trim(s)
}


fn albumIntro2(desc, cat, count, statusLabel) {
  let s = trim(default(desc, ''))
  if s != '' { return s }
  let out = []
  if trim(default(cat, '')) != '' { out = push(out, cat) }
  if int(str(default(count, 0))) > 0 { out = push(out, '共' + str(count) + '集') }
  if trim(default(statusLabel, '')) != '' { out = push(out, statusLabel) }
  return join(out, ' · ')
}

