// 听世界 × 275fm（听友听书）双端书源
// 搜索：听世界 /tingyou-app/search（站内 + 听友 AI 检索合并，两页合并，按 book_id 去重，精确匹配优先）
// 发现：275fm /listening-api/rank 与 /listening-api/category
// 详情：先用 book_id 回查听世界站内专辑；有站内专辑走听世界音轨，没有就走 275fm 章节/播放，无需提取
const TY_BASE = 'https://api.365ting.com';
const FM_BASE = 'https://fmfm.tingyou.fm';
const FM_HEADERS = {
  'Origin': 'https://fmfm.tingyou.fm',
  'Referer': 'https://fmfm.tingyou.fm/listening',
  'x-listening-timezone': 'Asia/Shanghai'
};

function jCleanTitle(t) {
  let s = String(t == null ? '' : t).trim();
  s = s.replace(/^(?:【[^【】]*】)+/, '').trim();
  let main = s.split(/[|丨｜]/)[0].trim();
  main = main.replace(/[、,，/|\s]+$/, '').replace(/[-—·:：]+$/, '').trim();
  if (main.length >= 2) return main;
  return s;
}

function jFmtDur(sec) {
  const s = Math.floor(Number(sec) || 0);
  if (s <= 0) return '';
  const m = Math.floor(s / 60);
  const r = s % 60;
  return m + ':' + (r < 10 ? '0' + r : '' + r);
}

function jIsPromo(t) {
  const s = String(t == null ? '' : t).toLowerCase();
  if (!s) return false;
  return /片花|预告|主题曲|主题歌|主题音乐|pv|宣传|片头曲|片尾曲|以音代序|大咖推荐|发刊词|小剧场|简介|作者的话|邀你来听|提前解锁|免费畅听|听友群|新专辑/.test(s);
}

function jRefDuration(tracks) {
  let ref = 0;
  let i;
  for (i = 0; i < tracks.length && i < 30; i++) {
    const d = Math.floor(Number(tracks[i].duration) || 0);
    if (d > ref) ref = d;
  }
  if (ref <= 0) {
    for (i = 0; i < tracks.length && i < 300; i++) {
      const d = Math.floor(Number(tracks[i].duration) || 0);
      if (d > ref) ref = d;
    }
  }
  return ref;
}

function jDropPromos(tracks) {
  if (!Array.isArray(tracks)) return [];
  const ref = jRefDuration(tracks);
  const out = [];
  let i;
  for (i = 0; i < tracks.length; i++) {
    const t = tracks[i] || {};
    const d = Math.floor(Number(t.duration) || 0);
    const kw = i < 8 && jIsPromo(t.title);
    const short = ref > 0 && i < 5 && d > 0 && d < 200 && d * 100 < ref * 12;
    if (!kw && !short) out.push(t);
  }
  return out;
}

function jBookId(url) {
  const s = String(url || '');
  let m = s.match(/\/listening\/album\/(\d+)/);
  if (m) return m[1];
  m = s.match(/\/listening-api\/chapters\/(\d+)/);
  if (m) return m[1];
  m = s.match(/\/chapters\/(\d+)/);
  if (m) return m[1];
  m = s.match(/\/api\/albums\/(\d+)\//);
  if (m) return m[1];
  return '';
}

function jNormalize(it, label) {
  const o = it || {};
  const bid = String(o.book_id || o.id || '');
  let cat = String(o.cat || o.type || '有声专辑');
  if (cat === '站内已有' || cat === '可提取' || cat === '需提取') cat = '有声专辑';
  return {
    book_id: bid,
    title: String(o.title || ''),
    desc: String(o.description || o.intro || o.desc || ''),
    cover: String(o.cover_url || o.cover || ''),
    teller: String(o.teller || o.author || ''),
    author: String(o.author || ''),
    cat: cat,
    type: String(o.type || ''),
    count: Number(o.count || 0),
    album_id: Number(o.album_id || 0),
    status: o.status,
    status_label: label || ''
  };
}

function searchAlbums(ctx) {
  const key = String(ctx.key || '').trim();
  if (!key) return [];
  const q = encodeURIComponent(key);
  const reqs = [1, 2].map(function (p) {
    return {
      url: TY_BASE + '/tingyou-app/search?keyword=' + q + '&page=' + p,
      timeout: 12000
    };
  });
  const res = http.all(reqs, { concurrency: 2, timeout: 12000 });
  const map = {};
  const order = [];
  let i, j;
  for (i = 0; i < res.length; i++) {
    if (!res[i] || !res[i].ok) continue;
    let d = null;
    try { d = res[i].json(); } catch (e) { continue; }
    const items = d && d.data && Array.isArray(d.data.items) ? d.data.items : [];
    for (j = 0; j < items.length; j++) {
      const raw = items[j] || {};
      const bid = String(raw.book_id || raw.id || '');
      if (!bid) continue;
      const local = Number(raw.album_id || 0) > 0;
      const item = jNormalize(raw, local ? '站内已有' : '在线可播');
      if (!map[bid]) {
        map[bid] = item;
        order.push(bid);
      } else if (local && map[bid].album_id <= 0) {
        map[bid] = item;
      }
    }
  }
  let out = order.map(function (b) { return map[b]; });
  // 听世界站内只覆盖了一部分专辑；命中太少时用 275fm 的完整检索兜底。
  if (out.length < 5) {
    const fmReqs = [1, 2].map(function (p) {
      return {
        url: FM_BASE + '/listening-api/search',
        method: 'POST',
        body: { keyword: key, page: p },
        headers: FM_HEADERS,
        timeout: 15000
      };
    });
    const fr = http.all(fmReqs, { concurrency: 2, timeout: 15000 });
    for (i = 0; i < fr.length; i++) {
      if (!fr[i] || !fr[i].ok) continue;
      let d = null;
      try { d = fr[i].json(); } catch (e) { continue; }
      const items = d && Array.isArray(d.results) ? d.results : [];
      for (j = 0; j < items.length; j++) {
        const raw = items[j] || {};
        const bid = String(raw.id || '');
        if (!bid || map[bid]) continue;
        map[bid] = jNormalize(raw, raw.status == 1 ? '连载' : '完结');
        order.push(bid);
      }
    }
    out = order.map(function (b) { return map[b]; });
  }
  const keyLower = key.toLowerCase();
  const score = function (t) {
    const c = String(t || '').trim().toLowerCase();
    if (c === keyLower) return 3;
    if (c.indexOf(keyLower) === 0) return 2;
    if (c.indexOf(keyLower) >= 0) return 1;
    return 0;
  };
  out.sort(function (a, b) {
    const sa = score(a.title);
    const sb = score(b.title);
    if (sa !== sb) return sb - sa;
    const la = a.album_id > 0 ? 1 : 0;
    const lb = b.album_id > 0 ? 1 : 0;
    if (la !== lb) return lb - la;
    return (b.count || 0) - (a.count || 0);
  });
  return out.slice(0, 30);
}


function detailBook(ctx) {
  const src = ctx.book || {};
  const out = {};
  let k;
  for (k in src) out[k] = src[k];
  const bid = jBookId(src.bookUrl);
  if (!bid) return out;
  const cacheKey = 'bid_' + bid;
  let local = cache.get(cacheKey);
  if (local === undefined || local === null || local === '') {
    local = 0;
    const r = http.get(TY_BASE + '/tingyou-app/search?keyword=' + bid, { timeout: 12000 });
    if (r.ok) {
      try {
        const d = r.json();
        const items = d && d.data && Array.isArray(d.data.items) ? d.data.items : [];
        let i;
        for (i = 0; i < items.length; i++) {
          if (String(items[i].book_id) === bid && Number(items[i].album_id) > 0) {
            local = Number(items[i].album_id);
            break;
          }
        }
      } catch (e) {}
    }
    cache.put(cacheKey, local, 6 * 3600);
  }
  out.tocUrl = local > 0
    ? TY_BASE + '/api/albums/' + local + '/tracks?user_id=-1'
    : FM_BASE + '/listening-api/chapters/' + bid;
  return out;
}

function tocBook(ctx) {
  const book = ctx.book || {};
  let tocUrl = String(book.tocUrl || '');
  if (!tocUrl) {
    const bid = jBookId(book.bookUrl);
    if (bid) tocUrl = FM_BASE + '/listening-api/chapters/' + bid;
  }
  if (tocUrl.indexOf('/api/albums/') >= 0) {
    const r = http.get(tocUrl, { timeout: 25000 });
    if (!r.ok) throw new Error('目录加载失败：' + r.status);
    const d = r.json();
    const tracks = Array.isArray(d.data) ? d.data : [];
    const clean = jDropPromos(tracks);
    return clean.map(function (t) {
      return {
        title: jCleanTitle(t.title),
        url: String(t.audio_url || ''),
        tag: jFmtDur(t.duration)
      };
    });
  }
  const r = http.get(tocUrl, { timeout: 30000 });
  if (!r.ok) throw new Error('目录加载失败：' + r.status);
  const d = r.json();
  const chapters = Array.isArray(d.chapters) ? d.chapters : [];
  const bid = jBookId(tocUrl) || jBookId(book.bookUrl);
  return chapters.map(function (c) {
    return {
      title: jCleanTitle(c.title),
      url: FM_BASE + '/listening/play/' + bid + '/' + c.index,
      tag: jFmtDur(c.duration)
    };
  });
}

function contentChapter(ctx) {
  const url = String((ctx.chapter && ctx.chapter.url) || '');
  if (url.indexOf('/listening/play/') < 0) return { audio: url };
  const m = url.match(/\/listening\/play\/(\d+)\/(\d+)/);
  if (!m) throw new Error('未知章节地址');
  const r = http.post(FM_BASE + '/listening-api/play', {
    album_id: m[1],
    chapter_idx: Number(m[2])
  }, { headers: FM_HEADERS, timeout: 20000 });
  if (!r.ok) throw new Error('播放地址获取失败：' + r.status);
  const d = r.json();
  if (!d || !d.play_url) throw new Error('播放地址为空');
  return { audio: d.play_url };
}

