fn deval(n, v) {
  let k = 0
  while k < 10 {
    if typeOf(v) != 'number' { return v }
    v = n[v]
    k = k + 1
  }
  return v
}

fn dramasOf(body) {
  let raw = match(body, 'id="__NUXT_DATA__"[^>]*>([\s\S]*?)</script>', 1)
  let n = json(raw)
  let out = []
  if n == null { return out }
  let seen = []
  let i = 0
  while i < len(n) {
    let v = n[i]
    if typeOf(v) == 'map' && get(v, 'cover') != null && get(v, 'title') != null {
      let rk = get(v, 'detail_route')
      if rk == null { rk = get(v, 'route') }
      if rk != null {
        let route = str(deval(n, rk))
        if route != '' && indexOf(join(seen, '|'), route) < 0 {
          push(seen, route)
          let name = str(deval(n, get(v, 'title')))
          let cov = deval(n, get(v, 'cover'))
          let cover = ''
          if typeOf(cov) == 'map' { cover = str(deval(n, get(cov, 'url'))) } else { cover = str(deval(n, cov)) }
          push(out, name + '\t' + route + '\t' + cover)
        }
      }
    }
    i = i + 1
  }
  return out
}

fn coverOf(body) {
  let raw = match(body, 'id="__NUXT_DATA__"[^>]*>([\s\S]*?)</script>', 1)
  let n = json(raw)
  if n == null { return '' }
  let i = 0
  while i < len(n) {
    let v = n[i]
    if typeOf(v) == 'map' && get(v, 'cover') != null && get(v, 'intro') != null {
      let c = deval(n, get(v, 'cover'))
      if typeOf(c) == 'map' { return str(deval(n, get(c, 'url'))) }
      return str(deval(n, c))
    }
    i = i + 1
  }
  return ''
}

fn introOf(body) {
  let raw = match(body, 'id="__NUXT_DATA__"[^>]*>([\s\S]*?)</script>', 1)
  let n = json(raw)
  if n == null { return '' }
  let i = 0
  while i < len(n) {
    let v = n[i]
    if typeOf(v) == 'map' && get(v, 'cover') != null && get(v, 'intro') != null {
      let t = str(deval(n, get(v, 'intro')))
      if t != '' { return t }
    }
    i = i + 1
  }
  return ''
}

