// 封面解码：站点图片是「首字节当 XOR key，其余字节逐字节异或，丢弃首字节」
// 签名（开发者 2026-11-06 回复）：coverDecode.script 在仅图片的沙箱里运行，入参为下载到的字节，返回图片字节
function decodeCover(bytes) {
  if (!bytes || bytes.length < 2) return bytes;
  var key = bytes[0];
  var out = new Uint8Array(bytes.length - 1);
  for (var i = 1; i < bytes.length; i++) out[i - 1] = bytes[i] ^ key;
  return out;
}

// zb 网关：AES-128-ECB(10 密钥轮换) + 设备免注册
var ZB_KEYS = ['6eIZ4cxM5pqzUXcF','84UZNK33cSVylz6Y','jeSWRcTwHyAKwJDB','i1hvJx9vuRt5zEBS',
  '1Yy1KOa75R7cnmkg','4MVTQQAJlMpUIAiL','T0RVp7KIPamrtQ33','8HbPxhX6fjhhhwok',
  'ugvseZc5Kkj8ecmV','G7i3OPcfNhBnAYpc'];

// 日期格式化：纯 JS，不依赖宿主内置函数
function zbDate(v) {
  if (!v) return '';
  var ms = Number(v);
  if (isNaN(ms)) return String(v);
  if (ms < 100000000000) ms = ms * 1000;
  var d = new Date(ms);
  if (isNaN(d.getTime())) return String(v);
  var p = function (n) { return n < 10 ? '0' + n : '' + n; };
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
}

// 32 位随机（注册 sign）：优先宿主 uuid，失败退回 Math.random
function zbRand32() {
  var s = '';
  try { s = String(uuid()).replace(/-/g, ''); } catch (e) { s = ''; }
  if (s.length >= 32) return s.slice(0, 32);
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  s = '';
  var seed = Date.now();
  for (var i = 0; i < 32; i++) {
    seed = (seed * 1103515245 + 12345) % 2147483647;
    s += chars.charAt(Math.abs(seed + Math.floor(Math.random() * 64)) % 64);
  }
  return s;
}

function zbBase(ctx) {
  var b = (ctx.vars.server || 'https://api.nmlfm5mav.xyz');
  while (b.length && b.charAt(b.length - 1) === '/') b = b.slice(0, b.length - 1);
  return b;
}
function zbSite(ctx) { return (ctx.vars.site || 'c3c111pd51.xyz'); }

// keyName: 'body' | 'params'（不同接口用不同键，错了报 BSC10003）
function zbRaw(ctx, uri, payload, method, jwt, keyName, cookie, accessToken) {
  var t = Date.now();
  var key = ZB_KEYS[t % 10];
  var inner = { method: (method === 1 ? 1 : 2), uri: uri };
  if (payload !== null && payload !== undefined) {
    if (keyName === 'body') inner.body = payload; else inner.params = payload;
  } else {
    if (keyName === 'body') inner.body = null; else inner.params = null;
  }
  var cipher = native.encrypt('AES/ECB/PKCS5Padding', JSON.stringify(inner), key);
  var data = native.bytesBase64(cipher);
  var headers = { 'Content-Type': 'application/json', 'Origin': 'https://' + zbSite(ctx) };
  if (jwt) headers['jwtToken'] = jwt;
  if (accessToken) headers['accessToken'] = accessToken;
  if (cookie) headers['Cookie'] = cookie;
  var r = http.post(zbBase(ctx) + '/fast-endecode/main/request',
    { data: data, time: t }, { headers: headers, timeout: 20000 });
  if (!r || !r.ok) { log('zbRaw http fail: ' + uri + ' ' + (r ? r.status : 'null')); return null; }
  var j = null;
  try { j = r.json(); } catch (e) { j = null; }
  if (!j || !j.data || j.time === undefined) { log('zbRaw bad body: ' + uri); return null; }
  var plain = null;
  try {
    var bytes = native.decrypt('AES/ECB/PKCS5Padding', native.base64Bytes(j.data), ZB_KEYS[Number(j.time) % 10]);
    plain = JSON.parse(native.fromBytes(bytes));
  } catch (e2) { log('zbRaw decrypt fail: ' + uri + ' ' + e2); return null; }
  return plain;
}

// 会话：设备免注册 → accessToken；再换 JWT；两者都缓存
function zbSession(ctx) {
  var st = { jwt: cache.get('zbJwt') || '', at: (ctx.vars.accessToken || '') || (vars.get('zbAccessToken') || '') };
  if (st.jwt) return st;

  var g = zbRaw(ctx, 'app/jwt-token', null, 1, null, 'params', '', '');
  var gjwt = g && g.result ? g.result : '';

  if (!st.at) {
    var sign = vars.get('zbSign') || '';
    if (!sign) { sign = zbRand32(); }
    var reg = zbRaw(ctx, 'user/register/free', {
      channelCode: '', key: '', osType: 'h5', sign: sign, machineCode: 'chrome',
      version: zbSite(ctx), domain: '', verifyCode: '', uuid: ''
    }, 2, gjwt, 'body', 'sign=' + sign, '');
    if (reg && reg.code === '0000' && reg.result && reg.result.accessToken) {
      st.at = reg.result.accessToken;
      vars.set('zbSign', sign);
      vars.set('zbAccessToken', st.at);
    } else {
      var why = reg ? (reg.code + ' ' + (reg.message || '')) : '接口无响应';
      log('zb 注册失败：' + why);
      cache.put('zbRegErr', why, 600);
    }
  }

  if (st.at) {
    var u = zbRaw(ctx, 'app/jwt-token', null, 1, st.at, 'params', 'accessToken=' + st.at, '');
    if (u && u.result) st.jwt = u.result;
  }
  if (!st.jwt) st.jwt = gjwt;
  if (st.jwt) cache.put('zbJwt', st.jwt, 6 * 3600);
  return st;
}

// 业务请求：1032/1033 时先刷 JWT，再失效则重注册
function zbApi(ctx, uri, payload, method, keyName) {
  var st = zbSession(ctx);
  var ck = st.at ? ('accessToken=' + st.at) : '';
  var r = zbRaw(ctx, uri, payload, method, st.jwt, keyName || 'params', ck, st.at);
  if (r && (r.code === '1032' || r.code === '1033' || r.code === '1034')) {
    // 第一次：只刷 JWT
    cache.put('zbJwt', '', 1);
    st = zbSession(ctx);
    ck = st.at ? ('accessToken=' + st.at) : '';
    r = zbRaw(ctx, uri, payload, method, st.jwt, keyName || 'params', ck, st.at);
    if (r && (r.code === '1032' || r.code === '1033')) {
      // 第二次：账号令牌已失效 → 丢弃并重新注册设备账号
      log('zb 令牌失效，重新注册：' + r.code);
      vars.set('zbAccessToken', '');
      cache.put('zbJwt', '', 1);
      st = zbSession(ctx);
      ck = st.at ? ('accessToken=' + st.at) : '';
      r = zbRaw(ctx, uri, payload, method, st.jwt, keyName || 'params', ck, st.at);
    }
  }
  return r;
}

function zbCfg(ctx) {
  var c = cache.get('zbCfg');
  if (c) return c;
  var r = zbApi(ctx, 'config/query', {
    groupKey: 'APP',
    key: 'picBaseUrl,newPicBaseUrl,playLines,h5_play_line,pc_play_line,mp4Domain,registerVerify'
  }, 1);
  c = (r && r.result) ? r.result : {};
  cache.put('zbCfg', c, 86400);
  return c;
}
function zbPicBase(ctx) {
  var c = zbCfg(ctx);
  return c.picBaseUrl || c.newPicBaseUrl || 'https://qv1tx2.shoupingxz.com';
}
function zbPlayHost(ctx) {
  var c = zbCfg(ctx);
  var want = ctx.vars.lineName || '国线1';
  var groups = [c.h5_play_line, c.pc_play_line, c.playLines];
  for (var i = 0; i < groups.length; i++) {
    var arr = null;
    try { arr = JSON.parse(groups[i] || '[]'); } catch (e) { arr = null; }
    if (!arr || !arr.length) continue;
    for (var k = 0; k < arr.length; k++) {
      if (arr[k] && arr[k].name === want && arr[k].line) return arr[k].line;
    }
    for (var m = 0; m < arr.length; m++) {
      if (arr[m] && arr[m].line) return arr[m].line;
    }
  }
  return 'https://rr.rxjhwl.com';
}

function zbImg(ctx, p) {
  if (!p) return '';
  if (String(p).indexOf('http') === 0) return p;
  var base = zbPicBase(ctx);
  return String(p).charAt(0) === '/' ? (base + p) : (base + '/' + p);
}

// 列表项 → 书籍
function zbBook(ctx, v) {
  var id = v.id || v.vodId || '';
  var kind = '';
  var tags = v.tags || [];
  if (tags && tags.length) kind = tags.slice(0, 5).join(',');
  if (v.vodDuration) kind = (kind ? kind + ' · ' : '') + Math.round(Number(v.vodDuration) / 60) + '分钟';
  if (v.readNumber) kind += ' · 👀' + v.readNumber;
  var author = '';
  if (v.authors && v.authors.nickName) author = v.authors.nickName;
  else if (v.authorName) author = v.authorName;
  var introParts = [];
  if (author) introParts.push('作者：' + author);
  if (v.group_names) introParts.push('分类：' + (v.group_names.length > 30 ? v.group_names.slice(0, 30) : v.group_names));
  if (kind) introParts.push(kind);
  if (v.vodVersion) introParts.push('清晰度：' + v.vodVersion);
  if (v.comments) introParts.push('评论 ' + v.comments);
  return {
    name: v.title || ('视频 ' + id),
    bookUrl: zbBase(ctx) + '/cms/vod/detail/' + id,
    coverUrl: zbImg(ctx, v.vodPic || v.vodPicInfo || v.gif || ''),
    kind: kind,
    intro: v.description || introParts.join(' · '),
    author: author,
    lastChapter: (v.createTime || v.vodTime) ? zbDate(v.createTime || v.vodTime) : '',
    type: 'video'
  };
}

function zbBooks(ctx, r) {
  var out = [];
  if (!r || !r.data) return out;
  var arr = r.data;
  for (var i = 0; i < arr.length; i++) {
    var b = zbBook(ctx, arr[i] || {});
    if (b.name && b.bookUrl) out.push(b);
  }
  return out;
}

function zbId(url) {
  var m = String(url || '').match(/(\d+)\s*$/);
  return m ? m[1] : '';
}

// ---------- 阶段函数 ----------
// 标签（采样 Top，标签即关键词，命中 20 万+）
var ZB_TAGS = ['诱惑', '挑逗', '骚货', '骚逼', '丝袜', '学生', '自拍', '口交', '后入', '巨乳', '素人', '制服'];

function zbClip(t, n) {
  t = String(t || '');
  return t.length > n ? t.slice(0, n) + '…' : t;
}

function zbMenus(ctx) {
  var out = [
    { title: '热门' },
    { title: '推荐', url: 'rec' },
    { title: '最新', url: 'new' },
    { title: '排行榜', url: 'rank' }
  ];

  // 五大分类组全部展开（国产/日韩/欧美/其他），每组一个可折叠分组
  var packs = cache.get('zbPacks');
  if (!packs || !packs.length) {
    var r = zbApi(ctx, 'cms/group-in-packages', null, 1);
    packs = (r && r.data) ? r.data : [];
    if (packs.length) cache.put('zbPacks', packs, 86400);
  }
    for (var i = 0; i < packs.length; i++) {
    var p = packs[i] || {};
    var gs = p.groups || [];
    if (!gs.length) continue;
    out.push({ title: (p.name || '分类') });
    for (var k = 0; k < gs.length; k++) {
