    for (var t = 0; t < tmax; t++) {
      var th = themes[t] || {};
      if (!th.id) continue;
      out.push({ title: zbClip(th.title, 10), url: 'th:' + th.id });
    }
  }

  // 标签
  out.push({ title: '标签' });
  for (var g2 = 0; g2 < ZB_TAGS.length; g2++) {
    out.push({ title: ZB_TAGS[g2], url: 't:' + ZB_TAGS[g2] });
  }
  return out;
}

function zbExplore(ctx) {
  var u = ctx.url || '';
  var page = ctx.page || 1;
  var SIZE = 24;
  var params;
  if (u === 'rank') {
    // 按播放量排序（排行榜）
    params = { page: page, pageSize: SIZE, sortType: 3 };
  } else if (u === 'new') {
    // 最新池
    params = { page: page, pageSize: SIZE, sortType: 2, explore: true };
  } else if (u.indexOf('g:') === 0) {
    params = { page: page, pageSize: SIZE, groupIds: Number(u.slice(2)) };
  } else if (u.indexOf('th:') === 0) {
    // 专题（theme/all 的 id）
    params = { page: page, pageSize: SIZE, themeIds: Number(u.slice(3)) };
  } else if (u.indexOf('s:') === 0 || u.indexOf('t:') === 0) {
    params = { page: page, pageSize: SIZE, keyword: u.slice(2) };
  } else {
    // rec / 默认：推荐流
    params = { page: page, pageSize: SIZE, sortType: 2, explore: false };
  }
  return zbBooks(ctx, zbApi(ctx, 'cms/vod/search', params, 2));
}

function zbSearch(ctx) {
  var r = zbApi(ctx, 'cms/vod/search', { page: ctx.page, pageSize: 24, keyword: ctx.key }, 2);
  return zbBooks(ctx, r);
}

function zbDetailData(ctx, id) {
