  if (full) keep('zbPlayUrl', full);
  keep('zbVodId', String(vod.id || id));
  var b = zbBook(ctx, vod);
  b.name = vod.title || ctx.book.name;
  b.intro = vod.description || (b.intro || '');
  b.kind = (vod.tags || []).join(',');
