  var addr = '';
  if (vod && vod.vodFullPlayUrl && vod.vodFullPlayUrl[0]) addr = vod.vodFullPlayUrl[0].addr || '';
  var host = zbPlayHost(ctx);
  var url = addr ? (host + addr) : cached;
  if (!url) {
    var regErr = cache.get('zbRegErr') || '';
    var why = r && r.code && r.code !== '0000' ? ('接口返回 ' + r.code + ' ' + (r.message || '')) : '没有取到播放地址';
    if (r && (r.code === '1032' || r.code === '1033' || r.code === '1034')) {
      why += '（需要账号令牌：自动注册失败' + (regErr ? '，' + regErr : '') + '；可在书源设置里填 accessToken）';
    }
    return { mediaError: why };
  }
  var site = zbSite(ctx);
