function zbCheckSite(ctx) {
  var list = ['c3c111pd51.xyz', 'ri33hepf9l.xyz', '2ltkv38vf.xyz', 'xw5keiq1qj.xyz', ctx.vars.site || ''];
  var ok = [];
  for (var i = 0; i < list.length; i++) {
