    } catch (e) { log('检测失败 ' + d + '：' + e); }
  }
  if (!ok.length) return '候选域名都不可用；请从推广页 config/down 拿新域名后填进「站点域名」';
  return '可用站点：' + ok.join(' / ') + '（默认优先用第一个，可在设置里切换）';
}

const HG = 'https://hongguoduanju.com';
function hgRd(html){
  const m = String(html||'').match(/_ROUTER_DATA\s*=\s*/);
  if(!m) return null;
  const start = m.index + m[0].length;
  let depth=0, inS=false, esc=false;
  for(let i=start;i<html.length;i++){
    const c=html[i];
    if(inS){ if(esc) esc=false; else if(c==='\\') esc=true; else if(c==='"') inS=false; continue; }
    if(c==='"'){ inS=true; continue; }
    if(c==='{') depth++;
    else if(c==='}'){ depth--; if(depth===0){ return JSON.parse(html.slice(start,i+1)); } }
  }
  return null;
}
function hgNorm(v){
  const x = v || {};
  const tags = (x.tags||x.category_list||[]).map(function(t){ return typeof t==='string'? t : (t.name||''); }).filter(Boolean);
  return {
    name: x.series_name || x.series_title || x.name || '',
    coverUrl: x.series_cover || '',
    intro: x.series_intro || '',
    kind: tags.slice(0,4).join(','),
    type: 'video',
    bookUrl: HG + '/detail?series_id=' + (x.series_id || '')
  };
}
function hgSearch(ctx){
  http.get(HG + '/', {timeout:10000});
  const r = http.get(HG + '/api/search/result?aid=8662&query=' + encodeURIComponent(ctx.key) + '&page=' + (ctx.page||1), {timeout:15000});
  if(!r.ok) throw new Error('搜索失败 HTTP ' + r.status);
  const d = r.json();
  return (d.searchList||[]).map(function(it){ return hgNorm((it && it.video_data) || it); });
}
function hgExplore(ctx){
  const route = String(ctx.url||'real-drama').replace(/^.*?:/,'');
  const r = http.get(HG + '/category/' + route + '?page=' + (ctx.page||1), {timeout:20000});
  if(!r.ok) throw new Error('分类页失败 HTTP ' + r.status);
  const d = hgRd(r.body);
  const ld = (d && d.loaderData) || {};
  const keys = Object.keys(ld);
  let page = null;
  for(let i=0;i<keys.length;i++){
    const v = ld[keys[i]];
    if(keys[i].indexOf('category_')===0 && v && (v.recommendList || v.selectorList)){ page = v; break; }
  }
  return ((page && page.recommendList) || []).map(hgNorm);
}
function hgDetail(ctx){
  const url = (ctx.book && (ctx.book.bookUrl || ctx.book.url)) || ctx.url || '';
  const sid = (String(url).match(/series_id=(\d+)/)||[])[1] || '';
  if(!sid) throw new Error('缺少 series_id');
  const r = http.get(HG + '/detail?series_id=' + sid, {timeout:20000});
  if(!r.ok) throw new Error('详情页失败 HTTP ' + r.status);
  const d = hgRd(r.body);
  const sd = ((((d||{}).loaderData||{}).detail_page)||{}).seriesDetail || {};
  const actors = (sd.celebrities||[]).map(function(c){ return c.nickname; }).filter(Boolean);
  const acc = sd.accessible_episode_cnt || 0;
  keep('sid', sid);
  return {
    name: sd.series_name || '',
    author: actors.slice(0,3).join(' / '),
    intro: sd.series_intro || '',
    coverUrl: sd.series_cover || '',
    kind: (sd.tags||[]).slice(0,4).join(','),
    status: '完结',
    lastChapter: '全' + (sd.episode_cnt||0) + '集（免费' + acc + '集）',
    type: 'video',
    bookUrl: HG + '/detail?series_id=' + sid
  };
}
function hgToc(ctx){
  const sid = (ctx.book && ctx.book.vars && ctx.book.vars.sid) || '';
  if(!sid) throw new Error('缺少 series_id');
  const r = http.get(HG + '/detail?series_id=' + sid, {timeout:20000});
  if(!r.ok) throw new Error('目录失败 HTTP ' + r.status);
  const d = hgRd(r.body);
  const sd = ((((d||{}).loaderData||{}).detail_page)||{}).seriesDetail || {};
  const vids = sd.vid_list || [];
  const acc = sd.accessible_episode_cnt || 0;
  return vids.map(function(v,i){ return { title: '第' + (i+1) + '集', url: HG + '/player/' + sid + '/' + v }; });
}
function hgContent(ctx){
  const u = String((ctx.chapter && ctx.chapter.url) || '');
  const vid = (u.split('/').pop()||'').split('?')[0];
  if(!/^[0-9]+$/.test(vid)) throw new Error('集地址缺少 vid');
  const q = (ctx.vars && ctx.vars.q) || '1080';
