// ===== 站点说明 =====
// v.waiboys.com 是 mxone 模板，列表/详情/播放页全部服务端直出 HTML，不需要 webview。
// 原 JS 书源用 $.webview 跑 DOM 脚本、用 data:image 卡片唤起 showvideoplay；
// 这里改成：按卡片开头切段 + sel/selAll 取字段，播放地址直接给 content.video。

// ===== 列表：按卡片开头切段 =====
fn itemCards(html) { return split(default(html, ""), '<div class="module-item">') }
fn searchCards(html) { return split(default(html, ""), '<div class="video-info">') }

// 取开头的连续数字
fn digitsOf(v) {
  let s = default(v, "")
  let out = ""
  let i = 0
  while (i < len(s)) {
    let ch = substring(s, i, i + 1)
    if (indexOf("0123456789", ch) < 0) { return out }
    out = out + ch
    i = i + 1
  }
  return out
}

// /vod/play/id/1/sid/1/nid/12.html → 12
fn nidOf(u) {
  let s = default(u, "")
  let i = indexOf(s, "/nid/")
  if (i < 0) { return "" }
  return digitsOf(substring(s, i + 5, len(s)))
}

// ===== 选集 =====
// 详情页每个线路一个 module-blocklist，选集形如
// <a href="/vod/play/id/…/sid/S/nid/N.html" title="…"><span>第N期</span></a>
// 优先只取第一条线路 sid/1，并按地址去重（页面会把同一集渲染多次）。
fn pickEpisodes(urls, labels, onlyMain) {
  let out = []
  let seen = []
  let i = 0
  while (i < len(urls)) {
    let u = urls[i]
    let use = true
    if (onlyMain && !contains(u, "/sid/1/")) { use = false }
    if (use && indexOf(seen, u) < 0) {
      push(seen, u)
      let t = default(get(labels, i, ""), "")
      if (t == "") { t = "第" + nidOf(u) + "集" }
      push(out, {title: t, url: u})
    }
    i = i + 1
  }
  return out
}

fn episodeList(html) {
  let s = default(html, "")
  let urls = matchAll(s, '<a href="(/vod/play/[^"]+)"[^>]*><span>([^<]*)</span>', 1)
  let labels = matchAll(s, '<a href="(/vod/play/[^"]+)"[^>]*><span>([^<]*)</span>', 2)
  let main = pickEpisodes(urls, labels, true)
  if (len(main) > 0) { return main }
  let all = pickEpisodes(urls, labels, false)
  if (len(all) > 0) { return all }
  // 电影没有选集列表，只有“立刻播放”按钮
  let btn = matchAll(s, '<a href="(/vod/play/[^"]+)" title="立刻播放', 1)
  if (len(btn) > 0) { return [{title: "正片", url: first(btn)}] }
  return []
}

// ===== 播放地址 =====
// 播放页里有 <a id="bfurl" href="…">：可能是完整 m3u8，也可能是 CDN 短链
// （短链返回一个播放页，源码里 const vid = "短链/index.m3u8"），所以短链补 /index.m3u8。
fn m3u8Of(html) {
  let s = default(html, "")
  let v = default(sel("a#bfurl@href", s), "")
  if (v == "") {
    // 兜底：进页面里 player 配置的 url 字段（斜杠被转义成 \/）
    v = default(first(matchAll(s, 'url":"(https?[^"]{8,300})"', 1)), "")
    v = replaceText(v, "\\/", "/")
  }
  if (v == "") { return "" }
  if (contains(v, "m3u8")) { return v }
  return v + "/index.m3u8"
}

fn sgn(qs, ts) {
  return sha1(md5((qs == '' ? '' : qs + '&') + 'key=cb808529bae6b6be45ecfab29a4889bc&t=' + ts))
}

