const SITE = 'https://cj.ffzyapi.com';
function episodes(d) {
  const arr = d && d.list ? d.list : [];
  const it = arr.length ? arr[0] : null;
  if (!it) return [];
  const groups = String(it.vod_play_url || '').split('$$$');
  let best = null;
  let bestScore = -1;
  for (let i = 0; i < groups.length; i++) {
    const parts = groups[i].split('#');
    const list = [];
    let hls = 0;
    for (let j = 0; j < parts.length; j++) {
      const e = parts[j];
      const k = e.indexOf('$');
      if (k <= 0) continue;
      const name = e.slice(0, k).trim();
      const url = e.slice(k + 1).trim();
      if (!name || !url) continue;
      if (url.indexOf('.m3u8') >= 0) hls += 1;
      list.push({ title: name, url: url });
    }
    if (!list.length) continue;
    const score = list.length + (hls === list.length ? 100000 : (hls > 0 ? 50000 : 0));
    if (score > bestScore) { bestScore = score; best = list; }
  }
  return best || [];
}
